import { Button } from "./Button";
import type { ReactNode } from "react";
import { useRef, useEffect, useId } from "react";
import { createPortal } from "react-dom";

type ModalShellProps = {
  title: string;
  children: ReactNode;
  actions?: ReactNode;
  onClose: () => void;
  zIndexClass?: string;
};

/**
 * Modal with:
 * - Focus trap (keyboard navigation stays within modal)
 * - Escape key closes modal
 * - aria-labelledby pointing to the title heading
 * - Initial focus on first focusable element
 * - WCAG 2.1.1, 2.4.3, 4.1.2 compliant
 */
export function Modal({ title, children, actions, onClose, zIndexClass = "z-[80]" }: ModalShellProps) {
  const modalRef = useRef<HTMLElement>(null);
  const titleId = useId();

  useEffect(() => {
    const el = modalRef.current;
    if (!el) return;

    // Find all focusable elements within the modal
    const focusableSelectors =
      'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';
    const getFocusable = () =>
      Array.from(el.querySelectorAll<HTMLElement>(focusableSelectors)).filter(
        (node) => !node.closest("[hidden]")
      );

    // Set initial focus on first focusable element
    const focusables = getFocusable();
    focusables[0]?.focus();

    function handleKeyDown(e: KeyboardEvent) {
      if (e.key === "Escape") {
        e.stopPropagation();
        onClose();
        return;
      }

      if (e.key !== "Tab") return;

      const current = getFocusable();
      if (current.length === 0) return;

      const first = current[0];
      const last = current[current.length - 1];

      if (e.shiftKey) {
        // Shift+Tab: going backwards
        if (document.activeElement === first) {
          e.preventDefault();
          last.focus();
        }
      } else {
        // Tab: going forwards
        if (document.activeElement === last) {
          e.preventDefault();
          first.focus();
        }
      }
    }

    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [onClose]);

  return createPortal(
    <div
      className={`fixed inset-0 bg-slate-950/40 backdrop-blur-sm ${zIndexClass} flex items-center justify-center p-4`}
      role="presentation"
      onClick={onClose}
    >
      <section
        ref={modalRef}
        className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-card shadow-2xl w-full max-w-lg max-h-[90vh] flex flex-col overflow-hidden animate-in"
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between p-6 border-b border-slate-100 dark:border-slate-800">
          <h2
            id={titleId}
            className="text-xl font-semibold text-gray-900 dark:text-slate-50 dark:text-slate-100 font-sans"
          >
            {title}
          </h2>
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={onClose}
            aria-label="Tutup dialog"
          >
            Tutup
          </Button>
        </div>
        <div className="p-6 overflow-y-auto">{children}</div>
        {actions && (
          <div className="p-6 border-t border-slate-100 bg-slate-50 dark:bg-slate-950 dark:bg-slate-900/50 dark:border-slate-800 flex items-center justify-end gap-3">
            {actions}
          </div>
        )}
      </section>
    </div>,
    document.body
  );
}

import { createContext, useContext, useState, useEffect, ReactNode, useCallback } from "react";
import { fetchCurrentUser, login, logout, registerOnUnauthorized } from "../lib/api";
import type { User } from "../types";
import { useAppFeedback } from "./FeedbackContext";

type AuthContextType = {
  user: User | null;
  authLoading: boolean;
  handleLogin: (user: User) => void;
  handleLogout: () => Promise<void>;
};

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const feedback = useAppFeedback();

  useEffect(() => {
    registerOnUnauthorized(() => {
      setUser(null);
    });

    let cancelled = false;
    async function bootAuth() {
      try {
        const current = await fetchCurrentUser();
        if (!cancelled) setUser(current.user);
      } catch (error: any) {
        // Ignore 401 on boot
        if (!cancelled && !(error?.status === 401)) {
          // feedback.pushError("Failed to fetch user");
        }
      } finally {
        if (!cancelled) setAuthLoading(false);
      }
    }
    void bootAuth();
    return () => { cancelled = true; };
  }, []);

  const handleLogin = useCallback((loggedInUser: User) => {
    setUser(loggedInUser);
  }, []);

  const handleLogout = useCallback(async () => {
    await feedback.withFeedback(async () => {
      await logout();
      setUser(null);
      feedback.pushSuccess("Sesi berhasil ditutup.");
    }, "logout");
  }, [feedback]);

  return (
    <AuthContext.Provider value={{ user, authLoading, handleLogin, handleLogout }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return context;
}

import { Button } from "../components/ui/Button";
import React, { createContext, useContext, useState, ReactNode } from "react";
import { Modal } from "../components/ui/Modal";

type DialogType = "alert" | "confirm";

type DialogState = {
  type: DialogType;
  title: string;
  message: string;
  resolve: (value: boolean) => void;
};

type DialogContextType = {
  showAlert: (message: string, title?: string) => Promise<void>;
  showConfirm: (message: string, title?: string) => Promise<boolean>;
};

const DialogContext = createContext<DialogContextType | undefined>(undefined);

export function DialogProvider({ children }: { children: ReactNode }) {
  const [dialog, setDialog] = useState<DialogState | null>(null);

  const showAlert = (message: string, title?: string) => {
    return new Promise<void>((resolve) => {
      setDialog({
        type: "alert",
        title: title || "Pemberitahuan",
        message,
        resolve: () => {
          setDialog(null);
          resolve();
        },
      });
    });
  };

  const showConfirm = (message: string, title?: string) => {
    return new Promise<boolean>((resolve) => {
      setDialog({
        type: "confirm",
        title: title || "Konfirmasi",
        message,
        resolve: (result) => {
          setDialog(null);
          resolve(result);
        },
      });
    });
  };

  return (
    <DialogContext.Provider value={{ showAlert, showConfirm }}>
      {children}
      {dialog && (
        <Modal
          title={dialog.title}
          onClose={() => dialog.resolve(false)}
          actions={
            dialog.type === "confirm" ? (
              <>
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => dialog.resolve(false)}
                >
                  Batal
                </Button>
                <Button
                  type="button"
                  variant="danger"
                  onClick={() => dialog.resolve(true)}
                >
                  Ya, Lanjutkan
                </Button>
              </>
            ) : (
              <Button
                type="button"
                variant="primary"
                onClick={() => dialog.resolve(true)}
              >
                OK
              </Button>
            )
          }
        >
          <p className="text-slate-600 dark:text-slate-300 whitespace-pre-wrap text-sm leading-relaxed">{dialog.message}</p>
        </Modal>
      )}
    </DialogContext.Provider>
  );
}

export function useDialog() {
  const context = useContext(DialogContext);
  if (!context) {
    throw new Error("useDialog must be used within a DialogProvider");
  }
  return context;
}

import { createContext, useContext, useState, ReactNode } from "react";
import type { ConfirmDialogState } from "../hooks/types";
import { toErrorMessage } from "../utils/format";
import { Modal } from "../components/ui/Modal";
import { ToastStack, type ToastItem } from "../components/ui/Toast";
import { Button } from "../components/ui/Button";

type FeedbackContextType = {
  submitting: boolean;
  busyAction: string | null;
  isBusy: (actionKey: string) => boolean;
  pushToast: (tone: ToastItem["tone"], message: string) => void;
  pushSuccess: (msg: string) => void;
  pushError: (msg: string) => void;
  pushWarning: (msg: string) => void;
  dismissToast: (id: number) => void;
  askForConfirmation: (config: ConfirmDialogState) => void;
  dismissConfirmDialog: () => void;
  confirmAndRun: () => Promise<void>;
  withFeedback: (action: () => Promise<void>, actionKey?: string) => Promise<void>;
};

const FeedbackContext = createContext<FeedbackContextType | undefined>(undefined);

export function FeedbackProvider({ children }: { children: ReactNode }) {
  const [submitting, setSubmitting] = useState(false);
  const [busyAction, setBusyAction] = useState<string | null>(null);
  const [toasts, setToasts] = useState<ToastItem[]>([]);
  const [confirmDialog, setConfirmDialog] = useState<ConfirmDialogState | null>(null);

  function pushToast(tone: ToastItem["tone"], message: string) {
    const id = Date.now() + Math.floor(Math.random() * 1000);
    setToasts((current) => [...current, { id, tone, message }]);
    window.setTimeout(() => {
      setToasts((current) => current.filter((item) => item.id !== id));
    }, 4200);
  }

  function dismissToast(id: number) {
    setToasts((current) => current.filter((item) => item.id !== id));
  }

  function pushSuccess(msg: string) { pushToast("success", msg); }
  function pushError(msg: string) { pushToast("error", msg); }
  function pushWarning(msg: string) { pushToast("warning", msg); }

  function askForConfirmation(config: ConfirmDialogState) {
    setConfirmDialog(config);
  }

  function dismissConfirmDialog() {
    setConfirmDialog(null);
  }

  async function confirmAndRun() {
    if (!confirmDialog) return;
    const action = confirmDialog.onConfirm;
    setConfirmDialog(null);
    await action();
  }

  async function withFeedback(action: () => Promise<void>, actionKey?: string) {
    setSubmitting(true);
    setBusyAction(actionKey ?? null);
    try {
      await action();
    } catch (caughtError) {
      pushError(toErrorMessage(caughtError));
    } finally {
      setSubmitting(false);
      setBusyAction(null);
    }
  }

  function isBusy(actionKey: string) {
    return submitting && busyAction === actionKey;
  }

  const value: FeedbackContextType = {
    submitting,
    busyAction,
    isBusy,
    pushToast,
    pushSuccess,
    pushError,
    pushWarning,
    dismissToast,
    askForConfirmation,
    dismissConfirmDialog,
    confirmAndRun,
    withFeedback,
  };

  return (
    <FeedbackContext.Provider value={value}>
      {children}
      <ToastStack toasts={toasts} onDismiss={dismissToast} />
      {confirmDialog && (
        <Modal
          title={confirmDialog.title}
          onClose={dismissConfirmDialog}
          actions={
            <>
              <Button
                variant="outline"
                onClick={dismissConfirmDialog}
                disabled={submitting}
              >
                Batal
              </Button>
              <Button
                variant={confirmDialog.tone === "danger" ? "danger" : "primary"}
                onClick={() => void confirmAndRun()}
                disabled={submitting}
              >
                {submitting ? "Memproses..." : "Ya, Lanjutkan"}
              </Button>
            </>
          }
        >
          <p className="text-slate-600 dark:text-slate-400">{confirmDialog.body}</p>
        </Modal>
      )}
    </FeedbackContext.Provider>
  );
}

export function useAppFeedback() {
  const context = useContext(FeedbackContext);
  if (context === undefined) {
    throw new Error("useAppFeedback must be used within a FeedbackProvider");
  }
  return context;
}

import { createContext, useContext, useEffect, useState, ReactNode } from "react";

type ThemeContextType = {
  theme: "light" | "dark";
  toggleTheme: () => void;
};

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

export function ThemeProvider({ children }: { children: ReactNode }) {
  const [theme, setTheme] = useState<"light" | "dark">(() => {
    if (typeof localStorage !== "undefined") {
      const stored = localStorage.getItem("theme");
      if (stored === "dark" || stored === "light") return stored;
    }
    return "light";
  });

  useEffect(() => {
    const root = window.document.documentElement;
    if (theme === "dark") {
      root.classList.add("dark");
    } else {
      root.classList.remove("dark");
    }
    localStorage.setItem("theme", theme);
  }, [theme]);

  const toggleTheme = () => setTheme((prev) => (prev === "light" ? "dark" : "light"));

  return (
    <ThemeContext.Provider value={{ theme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
}

export function useTheme() {
  const context = useContext(ThemeContext);
  if (context === undefined) {
    throw new Error("useTheme must be used within a ThemeProvider");
  }
  return context;
}

import { useState, useMemo } from "react";
import { Button } from "../../components/ui/Button";
import { StatusPill, inputClassName } from "../../components/ui";
import { formatDateTime } from "../../utils/format";
import { ChevronUp, ChevronDown, ArrowUpDown } from "lucide-react";
import type { AuditLogItem } from "../../types";

type AuditLogsPageProps = {
  auditLogs: AuditLogItem[];
  submitting: boolean;
  onRefresh: () => void;
};

export function AuditLogsPage({ auditLogs, submitting, onRefresh }: AuditLogsPageProps) {
  const [actionFilter, setActionFilter] = useState("");
  const [dateFilter, setDateFilter] = useState("");
  const [searchTerm, setSearchTerm] = useState("");

  const [sortField, setSortField] = useState<string | null>("created_at");
  const [sortDirection, setSortDirection] = useState<"asc" | "desc">("desc");

  const requestSort = (field: string) => {
    if (sortField === field) {
      setSortDirection((prev) => (prev === "asc" ? "desc" : "asc"));
    } else {
      setSortField(field);
      setSortDirection("asc");
    }
  };

  const renderSortableHeader = (label: string, field: string) => {
    const isSorted = sortField === field;
    return (
      <th 
        className="px-6 py-4 font-medium select-none cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors text-slate-500 dark:text-slate-400"
        onClick={() => requestSort(field)}
      >
        <div className="inline-flex items-center gap-1.5">
          <span>{label}</span>
          {isSorted ? (
            sortDirection === "asc" ? (
              <ChevronUp size={12} className="text-indigo-600 dark:text-indigo-400 stroke-[3]" />
            ) : (
              <ChevronDown size={12} className="text-indigo-600 dark:text-indigo-400 stroke-[3]" />
            )
          ) : (
            <ArrowUpDown size={12} className="text-slate-300 dark:text-slate-600 opacity-50 transition-opacity" />
          )}
        </div>
      </th>
    );
  };

  const uniqueActions = useMemo(() => {
    const actions = new Set<string>();
    auditLogs.forEach((log) => actions.add(log.action));
    return Array.from(actions).sort();
  }, [auditLogs]);

  const filteredLogs = useMemo(() => {
    return auditLogs.filter((log) => {
      const matchAction = !actionFilter || log.action === actionFilter;
      const matchDate = !dateFilter || log.created_at.startsWith(dateFilter);
      const matchSearch = !searchTerm || 
        (log.username && log.username.toLowerCase().includes(searchTerm.toLowerCase())) ||
        (log.message && log.message.toLowerCase().includes(searchTerm.toLowerCase())) ||
        (log.ip_address && log.ip_address.toLowerCase().includes(searchTerm.toLowerCase())) ||
        (log.action && log.action.toLowerCase().includes(searchTerm.toLowerCase()));
      return matchAction && matchDate && matchSearch;
    });
  }, [auditLogs, actionFilter, dateFilter, searchTerm]);

  const sortedLogs = useMemo(() => {
    const list = filteredLogs;
    if (!sortField) return list;
    return [...list].sort((a, b) => {
      let aVal = (a as any)[sortField];
      let bVal = (b as any)[sortField];

      const isNumericField = sortField === "id";
      if (aVal === null || aVal === undefined) aVal = isNumericField ? 0 : "";
      if (bVal === null || bVal === undefined) bVal = isNumericField ? 0 : "";

      if (isNumericField) {
        return sortDirection === "asc" ? aVal - bVal : bVal - aVal;
      }

      const aStr = String(aVal).trim().toLowerCase();
      const bStr = String(bVal).trim().toLowerCase();
      return sortDirection === "asc"
        ? aStr.localeCompare(bStr, undefined, { numeric: true, sensitivity: "base" })
        : bStr.localeCompare(aStr, undefined, { numeric: true, sensitivity: "base" });
    });
  }, [filteredLogs, sortField, sortDirection]);

  return (
    <section className="grid gap-6">
      <article className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-card p-6 shadow-sm">
        <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 flex-1">
            <label className="block">
              <span className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-2 block">Cari Log</span>
              <input
                type="text"
                placeholder="Cari user, IP, aksi, atau detail..."
                className="bg-white dark:bg-slate-900 border border-slate-250 text-slate-700 dark:text-slate-300 text-xs rounded-lg px-2.5 py-1.5 focus:outline-none focus:ring-1 focus:ring-indigo-500 w-full"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </label>
            <label className="block">
              <span className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-2 block">Filter Aksi</span>
              <select
                className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-slate-700 dark:text-slate-300 text-xs rounded-lg px-2.5 py-1.5 focus:outline-none focus:ring-1 focus:ring-indigo-500 w-full"
                value={actionFilter}
                onChange={(e) => setActionFilter(e.target.value)}
              >
                <option value="">Semua Aksi</option>
                {uniqueActions.map((action) => (
                  <option key={action} value={action}>{action}</option>
                ))}
              </select>
            </label>
            <label className="block">
              <span className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-2 block">Filter Tanggal</span>
              <input
                type="date"
                className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-slate-700 dark:text-slate-300 text-xs rounded-lg px-2.5 py-1.5 focus:outline-none focus:ring-1 focus:ring-indigo-500 w-full"
                value={dateFilter}
                onChange={(e) => setDateFilter(e.target.value)}
              />
            </label>
          </div>
          <div className="flex items-center gap-3">
              <Button
                type="button"
                variant="outline"
                size="sm"
                className="!text-indigo-700 !h-8 !px-3"
                disabled={submitting}
                onClick={() => {
                  setActionFilter("");
                  setDateFilter("");
                  setSearchTerm("");
                  onRefresh();
                }}
              >
                Refresh Data
              </Button>
            <StatusPill label={`${filteredLogs.length} event`} tone="slate" />
          </div>
        </div>
      </article>

      <article className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-card p-6 shadow-sm overflow-hidden">
        <div className="overflow-x-auto border border-slate-100 dark:border-slate-800 rounded-xl">
          <table className="w-full text-left border-collapse text-sm">
            <thead className="bg-slate-50 dark:bg-slate-950 border-b border-slate-100 dark:border-slate-800 text-slate-500 dark:text-slate-400">
              <tr>
                {renderSortableHeader("Waktu", "created_at")}
                {renderSortableHeader("User", "username")}
                {renderSortableHeader("IP", "ip_address")}
                {renderSortableHeader("Aksi", "action")}
                <th className="px-6 py-4 font-medium text-slate-500 dark:text-slate-400">Detail</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {sortedLogs.length === 0 ? (
                <tr>
                  <td className="px-6 py-12 text-center text-slate-400 dark:text-slate-500" colSpan={5}>
                    {auditLogs.length === 0 ? "Belum ada audit log." : "Tidak ada log yang cocok dengan filter."}
                  </td>
                </tr>
              ) : (
                sortedLogs.map((log) => (
                  <tr key={log.id} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-6 py-4 text-slate-700 dark:text-slate-300 whitespace-nowrap">{formatDateTime(log.created_at)}</td>
                    <td className="px-6 py-4 text-slate-700 dark:text-slate-300 font-medium">{log.username ?? (log.user_id ? `#${log.user_id}` : "-")}</td>
                    <td className="px-6 py-4 text-slate-400 dark:text-slate-500 text-xs font-mono">{log.ip_address || "-"}</td>
                    <td className="px-6 py-4">
                      <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-slate-100 text-slate-800 dark:text-slate-100">
                        {log.action}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-slate-600 leading-relaxed">{log.message || "-"}</td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </article>
    </section>
  );
}

