import { useState, useEffect } from "react";
import {
  fetchPendingConfirmations,
  approveConfirmation,
  rejectConfirmation,
  fetchBills,
  uploadBillProof,
  createPaymentConfirmation
} from "../../lib/api";
import type { PaymentConfirmationItem, BillItem } from "../../types";
import { formatCurrency } from "../../utils/format";
import { Check, X, Eye, FileText, AlertCircle } from "lucide-react";
import { useDialog } from "../../context/DialogContext";
import { Modal } from "../../components/ui/Modal";
import { Button } from "../../components/ui/Button";

type PaymentConfirmationsPageProps = {
  pushSuccess: (msg: string) => void;
  pushError: (msg: string) => void;
  withFeedback: (fn: () => Promise<void>, actionKey?: string) => Promise<void>;
};

export function PaymentConfirmationsPage({
  pushSuccess,
  pushError,
  withFeedback,
}: PaymentConfirmationsPageProps) {
  const [confirmations, setConfirmations] = useState<PaymentConfirmationItem[]>([]);
  const { showConfirm } = useDialog();
  const [loading, setLoading] = useState(false);
  const [busyId, setBusyId] = useState<number | null>(null);

  // Manual confirmation states
  const [showAddModal, setShowAddModal] = useState(false);
  const [unpaidBills, setUnpaidBills] = useState<BillItem[]>([]);
  const [loadingBills, setLoadingBills] = useState(false);
  const [selectedBillId, setSelectedBillId] = useState<number | null>(null);
  const [selectedLinkedBillIds, setSelectedLinkedBillIds] = useState<number[]>([]);
  const [uploadFile, setUploadFile] = useState<File | null>(null);
  const [catatanText, setCatatanText] = useState("");
  const [submitting, setSubmitting] = useState(false);

  const loadUnpaidBills = async () => {
    setLoadingBills(true);
    try {
      const res = await fetchBills({ status: "belum_bayar", limit: 200 });
      setUnpaidBills(res.data || []);
    } catch (err: any) {
      pushError(err.message || "Gagal memuat daftar tagihan");
    } finally {
      setLoadingBills(false);
    }
  };

  useEffect(() => {
    if (showAddModal) {
      void loadUnpaidBills();
    }
  }, [showAddModal]);

  const loadConfirmations = async () => {
    setLoading(true);
    try {
      const res = await fetchPendingConfirmations();
      setConfirmations(res.data || []);
    } catch (err: any) {
      pushError(err.message || "Gagal memuat konfirmasi pembayaran");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadConfirmations();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleApprove = async (id: number) => {
    setBusyId(id);
    try {
      await withFeedback(async () => {
        await approveConfirmation(id);
      }, `approve-${id}`);
      pushSuccess("Pembayaran berhasil disetujui.");
      setConfirmations((prev) => prev.filter((item) => item.id !== id));
    } catch (err: any) {
      pushError(err.message || "Gagal menyetujui pembayaran");
    } finally {
      setBusyId(null);
    }
  };

  const handleReject = async (id: number) => {
    if (!(await showConfirm("Apakah Anda yakin ingin menolak konfirmasi pembayaran ini?"))) return;
    setBusyId(id);
    try {
      await withFeedback(async () => {
        await rejectConfirmation(id);
      }, `reject-${id}`);
      pushSuccess("Konfirmasi pembayaran ditolak.");
      setConfirmations((prev) => prev.filter((item) => item.id !== id));
    } catch (err: any) {
      pushError(err.message || "Gagal menolak pembayaran");
    } finally {
      setBusyId(null);
    }
  };

  const resetForm = () => {
    setSelectedBillId(null);
    setSelectedLinkedBillIds([]);
    setUploadFile(null);
    setCatatanText("");
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedBillId) {
      pushError("Pilih tagihan terlebih dahulu.");
      return;
    }
    setSubmitting(true);
    try {
      let proofPath = "";
      if (uploadFile) {
        const uploadRes = await uploadBillProof(selectedBillId, uploadFile);
        proofPath = uploadRes.proof_path;
      }
      const selectedBill = unpaidBills.find(b => b.id === selectedBillId);
      if (!selectedBill) throw new Error("Tagihan tidak valid");

      await createPaymentConfirmation({
        tagihan_id: selectedBill.id,
        pelanggan_id: selectedBill.customer_id,
        bukti_transfer: proofPath || undefined,
        catatan: catatanText,
        linked_tagihan_ids: selectedLinkedBillIds.join(","),
      });

      pushSuccess("Konfirmasi pembayaran manual berhasil dibuat.");
      setShowAddModal(false);
      resetForm();
      void loadConfirmations();
    } catch (err: any) {
      pushError(err.message || "Gagal membuat konfirmasi pembayaran");
    } finally {
      setSubmitting(false);
    }
  };

  const isImage = (path?: string) => {
    if (!path) return false;
    const clean = path.toLowerCase().split("?")[0];
    return (
      clean.endsWith(".png") ||
      clean.endsWith(".jpg") ||
      clean.endsWith(".jpeg") ||
      clean.endsWith(".webp")
    );
  };

  const selectedBill = unpaidBills.find((b) => b.id === selectedBillId);
  const relatedBills = selectedBill
    ? unpaidBills.filter(
        (b) =>
          b.id !== selectedBill.id &&
          ((selectedBill.customer_phone && b.customer_phone === selectedBill.customer_phone) ||
            b.customer_id === selectedBill.customer_id)
      )
    : [];

  return (
    <section className="grid grid-cols-1 gap-6">
      <article className="bg-white dark:bg-slate-900 border border-gray-200 dark:border-slate-800 rounded-card p-6 shadow-sm">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
          <div>
            <h2 className="text-xl font-bold text-slate-900 dark:text-slate-50 dark:text-slate-55">Review Pembayaran</h2>
            <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">
              Verifikasi bukti transfer dan klaim pembayaran yang dikirimkan pelanggan melalui WhatsApp.
            </p>
          </div>
          <div className="flex gap-2">
            <Button onClick={() => setShowAddModal(true)} variant="primary">
                Tambah Konfirmasi Manual
              </Button>
            <Button
              variant="secondary"
              onClick={loadConfirmations}
              disabled={loading}
              isLoading={loading}
              loadingText="Menyegarkan..."
            >
              Segarkan
            </Button>
          </div>
        </div>

        {loading ? (
          <div className="py-20 text-center">
            <span className="text-sm text-slate-450">Memuat data review...</span>
          </div>
        ) : confirmations.length === 0 ? (
          <div className="py-20 flex flex-col items-center justify-center text-center bg-slate-50/50 dark:bg-slate-950/20 border border-dashed border-slate-200 dark:border-slate-800 rounded-card">
            <div className="w-12 h-12 bg-slate-100 dark:bg-slate-800 text-slate-400 dark:text-slate-500 rounded-card flex items-center justify-center mb-4">
              <Check className="w-6 h-6" />
            </div>
            <h3 className="font-bold text-slate-700 dark:text-slate-300 mb-1">Semua Bersih!</h3>
            <p className="text-xs text-slate-400 dark:text-slate-500 max-w-xs">
              Tidak ada bukti transfer atau klaim pembayaran yang pending untuk direview saat ini.
            </p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
            {confirmations.map((item) => {
              const date = new Date(item.created_at).toLocaleDateString("id-ID", {
                day: "numeric",
                month: "short",
                hour: "2-digit",
                minute: "2-digit",
              });
              const hasProof = !!item.bukti_transfer;
              const isImg = hasProof && isImage(item.bukti_transfer);

              return (
                <div
                  key={item.id}
                  className="bg-white dark:bg-slate-900 dark:bg-slate-850 border border-slate-200 dark:border-slate-800 rounded-card overflow-hidden flex flex-col justify-between shadow-sm hover:shadow-md transition-all duration-350"
                >
                  <div className="relative bg-slate-50 dark:bg-slate-950 dark:bg-slate-900 h-64 border-b border-slate-200 dark:border-slate-800 flex items-center justify-center overflow-hidden group">
                    {isImg ? (
                      <img
                        src={item.bukti_transfer}
                        alt="Bukti"
                        className="object-contain w-full h-full max-h-full transition-transform duration-500 group-hover:scale-105"
                      />
                    ) : hasProof ? (
                      <div className="flex flex-col items-center gap-3 p-6 text-slate-400 dark:text-slate-500">
                        <FileText className="w-16 h-16 text-indigo-400" />
                        <span className="text-xs font-semibold text-slate-500 dark:text-slate-400">File Non-Gambar</span>
                      </div>
                    ) : (
                      <div className="flex flex-col items-center gap-2 p-6 text-slate-450">
                        <AlertCircle className="w-12 h-12 text-amber-500" />
                        <span className="text-xs font-semibold text-slate-500 dark:text-slate-400">Klaim Tanpa Bukti (Cash)</span>
                      </div>
                    )}

                    {hasProof && (
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center gap-2 transition-opacity duration-200">
                        <a
                          href={item.bukti_transfer}
                          target="_blank"
                          rel="noreferrer"
                          className="bg-white dark:bg-slate-900 hover:bg-slate-100 text-slate-850 p-2.5 rounded-xl shadow-lg transition-transform hover:scale-110 flex items-center gap-1.5 text-xs font-bold"
                        >
                          <Eye className="w-4 h-4" /> Lihat Asli
                        </a>
                      </div>
                    )}
                  </div>

                  <div className="p-5 flex-1 flex flex-col justify-between">
                    <div>
                      <div className="flex justify-between items-start gap-2 mb-3">
                        <div>
                          <h4 className="font-bold text-slate-900 dark:text-slate-50 dark:text-slate-100 text-sm leading-tight">
                            {item.customer_name}
                          </h4>
                          <span className="text-[10px] text-indigo-650 dark:text-indigo-400 font-semibold tracking-wide uppercase mt-1 inline-block">
                            Invoice: {item.invoice_number}
                          </span>
                        </div>
                        <div className="text-right">
                          <span className="text-sm font-extrabold text-slate-900 dark:text-slate-50">
                            {formatCurrency(item.amount + (item.linked_bills || []).reduce((acc, b) => acc + b.amount, 0))}
                          </span>
                          {item.linked_bills && item.linked_bills.length > 0 && (
                            <span className="block text-[9px] text-indigo-600 dark:text-indigo-400 font-bold mt-0.5">
                              (Total {item.linked_bills.length + 1} Akun)
                            </span>
                          )}
                          <span className="block text-[10px] text-slate-400 dark:text-slate-500 mt-0.5">{date}</span>
                        </div>
                      </div>

                      {item.linked_bills && item.linked_bills.length > 0 && (
                        <div className="mt-2.5 mb-3 space-y-1.5 border-t border-slate-100 dark:border-slate-800 pt-2">
                          <span className="block text-[9px] text-slate-450 dark:text-slate-500 font-bold uppercase tracking-wider">
                            Akun Lain yang Ditautkan:
                          </span>
                          {item.linked_bills.map((lb) => (
                            <div key={lb.tagihan_id} className="flex justify-between items-center text-[11px] bg-slate-50 dark:bg-slate-950 dark:bg-slate-900/50 px-2.5 py-1.5 rounded-lg border border-slate-100 dark:border-slate-800">
                              <span className="text-slate-650 dark:text-slate-400 font-semibold">
                                {lb.invoice_number}
                              </span>
                              <span className="font-extrabold text-slate-800 dark:text-slate-100 dark:text-slate-300">
                                {formatCurrency(lb.amount)}
                              </span>
                            </div>
                          ))}
                        </div>
                      )}

                      <div className="bg-slate-50 dark:bg-slate-950 dark:bg-slate-900/60 rounded-xl p-3 text-xs text-slate-650 dark:text-slate-350 border border-slate-100 dark:border-slate-800">
                        <strong className="block text-[10px] text-slate-450 dark:text-slate-500 mb-1 tracking-wider uppercase">
                          Keterangan:
                        </strong>
                        <p className="italic leading-relaxed break-words whitespace-pre-line">
                          {item.catatan || "(tidak ada)"}
                        </p>
                      </div>
                    </div>

                    <div className="flex gap-3 mt-5 pt-4 border-t border-slate-100 dark:border-slate-800">
                      <Button
                          onClick={() => handleReject(item.id)}
                          disabled={busyId !== null}
                          variant="danger"
                          className="bg-rose-50 hover:bg-rose-100 dark:bg-rose-950/20 dark:hover:bg-rose-900/35 text-rose-600 flex-1"
                        >
                          <X className="w-4 h-4" /> Tolak
                        </Button>
                      <Button
                          onClick={() => handleApprove(item.id)}
                          disabled={busyId !== null}
                          variant="primary"
                          className="flex-1"
                        >
                          <Check className="w-4 h-4" /> Setujui
                        </Button>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </article>

      {showAddModal && (
        <Modal title="Tambah Konfirmasi Pembayaran Manual" onClose={() => setShowAddModal(false)}>
          <form onSubmit={handleSubmit} className="space-y-4 font-sans">
            <div>
              <label className="block text-xs font-semibold text-slate-700 dark:text-slate-300 dark:text-slate-355 mb-1">
                Pilih Tagihan Pelanggan (Belum Bayar) *
              </label>
              {loadingBills ? (
                <div className="text-xs text-slate-400 dark:text-slate-500 py-1">Memuat daftar tagihan...</div>
              ) : (
                <select
                  value={selectedBillId || ""}
                  onChange={(e) => {
                    setSelectedBillId(Number(e.target.value) || null);
                    setSelectedLinkedBillIds([]);
                  }}
                  className="w-full rounded-xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 text-xs px-3 py-2 text-slate-800 dark:text-slate-100 dark:text-slate-200"
                  required
                >
                  <option value="">-- Pilih Tagihan --</option>
                  {unpaidBills.map((bill) => (
                    <option key={bill.id} value={bill.id}>
                      {bill.customer_name} - {bill.invoice_number} ({formatCurrency(bill.amount)})
                    </option>
                  ))}
                </select>
              )}
            </div>

            {relatedBills.length > 0 && (
              <div className="bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl p-3 space-y-2">
                <span className="block text-[10px] font-bold text-indigo-650 dark:text-indigo-400 uppercase tracking-wider">
                  Tautkan Tagihan Lain (Multi-Akun / Nomer WA Sama)
                </span>
                <div className="space-y-1.5 max-h-36 overflow-y-auto pr-1">
                  {relatedBills.map((bill) => {
                    const isChecked = selectedLinkedBillIds.includes(bill.id);
                    return (
                      <label
                        key={bill.id}
                        className="flex items-center gap-2 text-xs text-slate-700 dark:text-slate-300 cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-900/60 p-1.5 rounded-lg transition-all"
                      >
                        <input
                          type="checkbox"
                          checked={isChecked}
                          onChange={(e) => {
                            if (e.target.checked) {
                              setSelectedLinkedBillIds((prev) => [...prev, bill.id]);
                            } else {
                              setSelectedLinkedBillIds((prev) => prev.filter((id) => id !== bill.id));
                            }
                          }}
                          className="rounded border-slate-300 dark:border-slate-800 text-indigo-600 focus:ring-indigo-500 w-3.5 h-3.5"
                        />
                        <span>
                          {bill.invoice_number} - {bill.package_name} ({formatCurrency(bill.amount)})
                        </span>
                      </label>
                    );
                  })}
                </div>
              </div>
            )}

            <div>
              <label className="block text-xs font-semibold text-slate-700 dark:text-slate-300 dark:text-slate-355 mb-1">
                Bukti Transfer (Gambar / PDF - Opsional)
              </label>
              <input
                type="file"
                accept="image/*,application/pdf"
                onChange={(e) => setUploadFile(e.target.files?.[0] || null)}
                className="w-full text-xs text-slate-500 dark:text-slate-400 file:mr-4 file:py-2 file:px-4 file:rounded-xl file:border-0 file:text-xs file:font-semibold file:bg-indigo-50 file:text-indigo-700 hover:file:bg-indigo-100"
              />
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 dark:text-slate-300 dark:text-slate-355 mb-1">
                Catatan Pembayaran
              </label>
              <textarea
                value={catatanText}
                onChange={(e) => setCatatanText(e.target.value)}
                placeholder="Contoh: Transfer Bank Mandiri an Pengirim"
                className="w-full rounded-xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 text-xs px-3 py-2 h-20 text-slate-800 dark:text-slate-100 dark:text-slate-200"
              />
            </div>

            <div className="flex justify-end gap-2 pt-2">
              <Button type="button" variant="outline" onClick={() => setShowAddModal(false)}>
                  Batal
                </Button>
              <Button
                type="submit"
                variant="primary"
                disabled={submitting}
                isLoading={submitting}
                loadingText="Menyimpan..."
              >
                Simpan Konfirmasi
              </Button>
            </div>
          </form>
        </Modal>
      )}
    </section>
  );
}

import { Button } from "../../components/ui/Button";
import { useState, useEffect, useMemo } from "react";
import { Loader2, Plus, ArrowUpDown, ChevronUp, ChevronDown, RefreshCw } from "lucide-react";
import { StatusPill, EmptyTableRow } from "../../components/ui";
import { Modal } from "../../components/ui/Modal";
import type { CustomerItem, PackageItem, User, OdpItem } from "../../types";
import type { FieldErrors } from "../../utils/validation";
import type { CustomerLifecycleEntry } from "../../lib/lifecycle";
import type { CustomerLifecycleFilter } from "../../hooks/useCustomers";
import { formatCurrency } from "../../utils/format";
import { displayStatusLabel, displayStatusTone } from "../../utils/status";
import { bulkUpdateCustomerStatus } from "../../lib/api";
import { useDialog } from "../../context/DialogContext";

import { CustomerFormCard } from "./components/CustomerFormCard";
import { BroadcastModal } from "./components/BroadcastModal";
import { CustomerDetailModal } from "./components/CustomerDetailModal";
import { MikrotikSyncModal } from "./components/MikrotikSyncModal";

export type CustomerFormState = {
  name: string;
  package_id: number;
  user_pppoe: string;
  password_pppoe: string;
  whatsapp: string;
  email: string;
  sn_ont: string;
  due_day: number;
  status: CustomerItem["status"];
  address: string;
  diskon: number;
  tipe_diskon: "flat" | "percent";
  referred_by_id: number;
  referral_balance: number;
  odp_id: number;
  odp_port?: number;
  is_trial: boolean;
  trial_days: number;
};

export const defaultCustomerForm = (): CustomerFormState => ({
  name: "",
  package_id: 0,
  user_pppoe: "",
  password_pppoe: "",
  whatsapp: "",
  email: "",
  sn_ont: "",
  due_day: 8,
  status: "active",
  address: "",
  diskon: 0,
  tipe_diskon: "flat",
  referred_by_id: 0,
  referral_balance: 0,
  odp_id: 0,
  odp_port: undefined,
  is_trial: false,
  trial_days: 3,
});

type CustomersPageProps = {
  user: User | null;
  packages: PackageItem[];
  customers: CustomerItem[];
  filteredCustomers: CustomerItem[];
  customerForm: CustomerFormState;
  customerErrors: FieldErrors;
  editingCustomerId: number | null;
  customerLifecycleFilter: CustomerLifecycleFilter;
  customerLifecycleMap: Record<number, CustomerLifecycleEntry>;
  submitting: boolean;
  busyAction: string | null;
  onFormChange: (updater: (current: CustomerFormState) => CustomerFormState) => void;
  onFilterChange: (filter: CustomerLifecycleFilter) => void;
  onSubmit: (e: React.FormEvent<HTMLFormElement>) => void;
  onStatusChange: (id: number, status: CustomerItem["status"]) => void;
  pushSuccess: (msg: string) => void;
  pushError: (msg: string) => void;
  onEdit: (customer: CustomerItem) => void;
  onCancelEdit: () => void;
  onRefresh?: () => void;
  onDelete: (id: number) => void;
  onDeleteBulk: (ids: number[]) => void;
  isFormOpen: boolean;
  onSetFormOpen: (open: boolean) => void;
  onEndTrial?: (id: number) => void;
};

export function CustomersPage({
  user,
  packages,
  customers,
  filteredCustomers,
  customerForm,
  customerErrors,
  editingCustomerId,
  customerLifecycleFilter,
  customerLifecycleMap,
  submitting,
  busyAction,
  onFormChange,
  onFilterChange,
  onSubmit,
  onStatusChange,
  onEdit,
  onCancelEdit,
  pushSuccess,
  pushError,
  onRefresh,
  onDelete,
  onDeleteBulk,
  isFormOpen,
  onSetFormOpen,
  onEndTrial,
}: CustomersPageProps) {
  const [selectedIds, setSelectedIds] = useState<Record<number, boolean>>({});
  const { showAlert, showConfirm } = useDialog();
  const [isBroadcastOpen, setIsBroadcastOpen] = useState(false);
  const [detailedCustomer, setDetailedCustomer] = useState<CustomerItem | null>(null);
  const [isSyncModalOpen, setIsSyncModalOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");

  const handleSelectSecret = (name: string, password: string, guessedPackageId: number) => {
    onCancelEdit();
    const today = new Date();
    const defaultTrialDays = 3;
    today.setDate(today.getDate() + defaultTrialDays + 5);
    const calculatedDueDay = today.getDate();

    onFormChange((curr) => ({
      ...curr,
      name: name,
      user_pppoe: name,
      password_pppoe: password,
      package_id: guessedPackageId,
      status: "trial",
      is_trial: true,
      trial_days: defaultTrialDays,
      due_day: calculatedDueDay,
    }));
    setIsSyncModalOpen(false);
    onSetFormOpen(true);
  };

  const [sortField, setSortField] = useState<string | null>("name");
  const [sortDirection, setSortDirection] = useState<"asc" | "desc">("asc");

  const requestSort = (field: string) => {
    if (sortField === field) {
      setSortDirection((prev) => (prev === "asc" ? "desc" : "asc"));
    } else {
      setSortField(field);
      setSortDirection("asc");
    }
  };

  const searchedCustomers = useMemo(() => {
    if (!searchQuery.trim()) return filteredCustomers;
    const q = searchQuery.toLowerCase();
    return filteredCustomers.filter(
      (c) =>
        (c.name || "").toLowerCase().includes(q) ||
        (c.user_pppoe || "").toLowerCase().includes(q) ||
        (c.address || "").toLowerCase().includes(q) ||
        (c.whatsapp || "").includes(q)
    );
  }, [filteredCustomers, searchQuery]);

  const sortedCustomers = [...searchedCustomers].sort((a, b) => {
    if (!sortField) return 0;
    
    let aVal: any = null;
    let bVal: any = null;
    
    if (sortField === "billing_lifecycle") {
      aVal = customerLifecycleMap[a.id]?.key ?? "";
      bVal = customerLifecycleMap[b.id]?.key ?? "";
    } else {
      aVal = (a as any)[sortField];
      bVal = (b as any)[sortField];
    }

    // Handle null/undefined values: treat as 0 for numbers, empty string for others
    const isNumericField = sortField === "due_day" || sortField === "diskon" || sortField === "referral_balance";
    if (aVal === null || aVal === undefined) {
      aVal = isNumericField ? 0 : "";
    }
    if (bVal === null || bVal === undefined) {
      bVal = isNumericField ? 0 : "";
    }

    if (isNumericField) {
      const aNum = Number(aVal);
      const bNum = Number(bVal);
      return sortDirection === "asc" ? aNum - bNum : bNum - aNum;
    }

    // Convert to string and case-insensitive compare with numeric support
    const aStr = String(aVal).trim().toLowerCase();
    const bStr = String(bVal).trim().toLowerCase();

    return sortDirection === "asc"
      ? aStr.localeCompare(bStr, undefined, { numeric: true, sensitivity: "base" })
      : bStr.localeCompare(aStr, undefined, { numeric: true, sensitivity: "base" });
  });

  const renderSortableHeader = (label: string, field: string, align: "left" | "center" = "left") => {
    const isSorted = sortField === field;
    const sortAria = isSorted ? (sortDirection === "asc" ? "ascending" : "descending") : "none";
    return (
      <th 
        className={`px-4 py-4 font-semibold select-none cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors ${align === "center" ? "text-center" : "text-left"}`}
        onClick={() => requestSort(field)}
        aria-sort={sortAria}
        scope="col"
      >
        <div className={`inline-flex items-center gap-1.5 ${align === "center" ? "justify-center w-full" : ""}`}>
          <span>{label}</span>
          {isSorted ? (
            sortDirection === "asc" ? (
              <ChevronUp size={12} className="text-indigo-600 dark:text-indigo-400 stroke-[3]" aria-hidden="true" />
            ) : (
              <ChevronDown size={12} className="text-indigo-600 dark:text-indigo-400 stroke-[3]" aria-hidden="true" />
            )
          ) : (
            <ArrowUpDown size={12} className="text-slate-300 dark:text-slate-600 opacity-50 transition-opacity" aria-hidden="true" />
          )}
        </div>
      </th>
    );
  };
  const [odps, setOdps] = useState<OdpItem[]>([]);

  const [isBulkEditOpen, setIsBulkEditOpen] = useState(false);
  const [bulkActionType, setBulkActionType] = useState<"status" | "package" | "odp" | "referral" | "delete">("status");
  const [bulkSearchQuery, setBulkSearchQuery] = useState("");
  const [selectedStatus, setSelectedStatus] = useState<CustomerItem["status"]>("active");
  const [selectedPackageId, setSelectedPackageId] = useState<number>(0);
  const [selectedOdpId, setSelectedOdpId] = useState<number | null>(null);
  const [selectedReferredById, setSelectedReferredById] = useState<number | null>(null);

  // Load ODP list
  useEffect(() => {
    fetch("/api/v1/odps", { credentials: "include" })
      .then((res) => res.json())
      .then((data) => setOdps(data.data || []))
      .catch(() => pushError("Gagal memuat data ODP. Silakan muat ulang halaman."));
  }, [pushError]);

  // Close form modal on successful save/update
  useEffect(() => {
    if (!submitting && Object.keys(customerErrors).length === 0 && !editingCustomerId) {
      onSetFormOpen(false);
    }
  }, [submitting, customerErrors, editingCustomerId, onSetFormOpen]);

  const selectedCount = Object.values(selectedIds).filter(Boolean).length;

  const handleOpenDetails = (customer: CustomerItem) => {
    setDetailedCustomer(customer);
  };

  const handleToggleSelectAll = (checked: boolean) => {
    const next: Record<number, boolean> = {};
    if (checked) {
      filteredCustomers.forEach((c) => {
        next[c.id] = true;
      });
    }
    setSelectedIds(next);
  };

  const handleApplyBulkChange = async () => {
    const ids = Object.entries(selectedIds)
      .filter(([_, val]) => val)
      .map(([id]) => Number(id));

    if (ids.length === 0) return;

    let confirmMsg = "";
    const payload: {
      ids: number[];
      status?: CustomerItem["status"];
      odp_id?: number | null;
      paket_id?: number;
      referred_by_id?: number | null;
    } = { ids };

    if (bulkActionType === "status") {
      payload.status = selectedStatus;
      confirmMsg = `Ubah status ${ids.length} pelanggan terpilih menjadi ${selectedStatus}?`;
    } else if (bulkActionType === "package") {
      if (!selectedPackageId) {
        await showAlert("Pilih paket internet terlebih dahulu!");
        return;
      }
      payload.paket_id = selectedPackageId;
      const pkgName = packages.find((p) => p.id === selectedPackageId)?.name || "";
      confirmMsg = `Ubah paket ${ids.length} pelanggan terpilih menjadi ${pkgName}?`;
    } else if (bulkActionType === "odp") {
      if (selectedOdpId === null) {
        await showAlert("Pilih ODP terlebih dahulu!");
        return;
      }
      payload.odp_id = selectedOdpId === -1 ? null : selectedOdpId;
      const odpName = selectedOdpId === -1 ? "Kosongkan/Hapus ODP" : odps.find((o) => o.id === selectedOdpId)?.nama || "";
      confirmMsg = `Ubah ODP ${ids.length} pelanggan terpilih menjadi ${odpName}?`;
    } else if (bulkActionType === "referral") {
      if (selectedReferredById === null) {
        await showAlert("Pilih referral terlebih dahulu!");
        return;
      }
      payload.referred_by_id = selectedReferredById === -1 ? null : selectedReferredById;
      const refName = selectedReferredById === -1 ? "Kosongkan/Hapus Referral" : customers.find((c) => c.id === selectedReferredById)?.name || "";
      confirmMsg = `Ubah Referral ${ids.length} pelanggan terpilih menjadi ${refName}?`;
    } else if (bulkActionType === "delete") {
      confirmMsg = `HAPUS secara permanen ${ids.length} pelanggan terpilih beserta semua PPP secret mereka di MikroTik? Tindakan ini tidak dapat dibatalkan!`;
    }

    if (await showConfirm(confirmMsg)) {
      try {
        if (bulkActionType === "delete") {
          await onDeleteBulk(ids);
        } else {
          await bulkUpdateCustomerStatus(
            payload.ids,
            payload.status,
            payload.odp_id === null ? -1 : payload.odp_id,
            payload.paket_id,
            payload.referred_by_id === null ? -1 : payload.referred_by_id
          );
        }
        pushSuccess(`Berhasil memproses aksi massal untuk ${ids.length} pelanggan.`);
        setSelectedIds({});
        setIsBulkEditOpen(false);
        if (onRefresh) onRefresh();
      } catch (err: any) {
        pushError(err.message || "Gagal melakukan aksi massal.");
      }
    }
  };

  const handleToggleSelectOne = (id: number, checked: boolean) => {
    setSelectedIds((prev) => ({ ...prev, [id]: checked }));
  };

  const handleCloseForm = () => {
    onSetFormOpen(false);
    onCancelEdit();
  };

  const showForm = isFormOpen || editingCustomerId !== null;

  return (
    <section className="flex flex-col gap-6 w-full">
      {/* Customer List Card (Full Width) */}
      <article className="bg-white dark:bg-slate-900 border border-gray-200 dark:border-slate-800 rounded-card p-6 shadow-sm overflow-hidden flex flex-col w-full">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
          <div>
            <h2 className="text-lg font-bold text-slate-900 dark:text-slate-50 font-sans">Daftar Pelanggan</h2>
            <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">Pantau status billing, paket, jatuh tempo, dan referral pelanggan dalam satu daftar terpadu.</p>
          </div>
          <div className="flex flex-wrap items-center gap-3">
            {user?.role !== "viewer" && (
              <Button
                type="button"
                variant="outline"
                className="bg-white dark:bg-slate-900 hover:bg-slate-50 dark:hover:bg-slate-800/40 dark:hover:bg-slate-800"
                onClick={() => setIsSyncModalOpen(true)}
                icon={<RefreshCw size={14} />}
              >
                Sync dari MikroTik
              </Button>
            )}
            {user?.role !== "viewer" && (
              <Button
                type="button"
                variant="primary"
                onClick={() => {
                  onCancelEdit();
                  onSetFormOpen(true);
                }}
                icon={<Plus size={14} />}
              >
                Tambah Pelanggan
              </Button>
            )}
            {user?.role !== "viewer" && (
              <Button
                type="button"
                variant="primary"
                onClick={() => setIsBroadcastOpen(true)}
                icon={<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"></path></svg>}
              >
                Broadcast WA {selectedCount > 0 ? `(${selectedCount})` : ""}
              </Button>
            )}
            {user?.role !== "viewer" && selectedCount > 0 && (
              <Button
                type="button"
                variant="outline"
                className="bg-indigo-50 hover:bg-indigo-100 text-indigo-700 border-indigo-200"
                onClick={() => {
                  setBulkActionType("status");
                  setBulkSearchQuery("");
                  setSelectedStatus("active");
                  setSelectedPackageId(0);
                  setSelectedOdpId(null);
                  setSelectedReferredById(null);
                  setIsBulkEditOpen(true);
                }}
              >
                Aksi Massal ({selectedCount})
              </Button>
            )}
            <div className="flex items-center gap-2 bg-white dark:bg-slate-900 border border-gray-200 dark:border-slate-800 rounded-xl px-3 py-1.5 shadow-sm font-sans w-full sm:w-64">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" className="text-slate-400 dark:text-slate-500 shrink-0"><circle cx="11" cy="11" r="8"></circle><line x1="21" y1="21" x2="16.65" y2="16.65"></line></svg>
              <input
                type="text"
                placeholder="Cari nama, pppoe, alamat..."
                className="bg-transparent border-0 text-xs font-semibold text-slate-750 dark:text-slate-200 focus:outline-none focus:ring-0 w-full py-0 pl-1 pr-1"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>
            <div className="flex items-center gap-2 bg-white dark:bg-slate-900 border border-gray-200 dark:border-slate-800 rounded-xl px-3 py-2 shadow-sm font-sans">
              <span className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider">Filter Role</span>
              <select
                className="bg-transparent border-0 text-xs font-semibold text-slate-750 dark:text-slate-200 focus:outline-none focus:ring-0 cursor-pointer py-0 pl-1 pr-6"
                value={customerLifecycleFilter}
                onChange={(e) => onFilterChange(e.target.value as CustomerLifecycleFilter)}
                aria-label="Filter role billing pelanggan"
              >
                <option value="exclude_inactive">Semua Kecuali Inactive</option>
                <option value="all">Semua (Termasuk Inactive)</option>
                <option value="trial">Trial Aktif</option>
                <option value="perpanjangan">Perpanjangan</option>
                <option value="tertagih">Tertagih</option>
                <option value="jatuh_tempo">Jatuh Tempo</option>
                <option value="menunggak">Menunggak</option>
                <option value="lunas">Lunas</option>
                <option value="wifi_umum">­ƒø£ WiFi Umum</option>
              </select>
            </div>
            <a
              href="/api/v1/reports/customers/csv"
              className="bg-emerald-600 hover:bg-emerald-700 text-white font-semibold py-2.5 px-4 rounded-xl text-xs shadow-sm transition-colors flex items-center gap-1.5"
            >
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="7 10 12 15 17 10"></polyline><line x1="12" y1="15" x2="12" y2="3"></line></svg>
              Export CSV
            </a>
            <StatusPill
              label={
                searchQuery.trim()
                  ? `${searchedCustomers.length} dari ${filteredCustomers.length} item`
                  : `${filteredCustomers.length} item`
              }
              tone="slate"
            />
          </div>
        </div>

        <div className="overflow-x-auto border border-gray-200 dark:border-slate-800 rounded-card bg-white dark:bg-slate-900 shadow-sm scrollbar-thin">
          <table className="w-full text-left border-collapse text-sm min-w-[1000px]">
            <thead className="bg-gray-50 dark:bg-slate-800 border-b border-gray-200 dark:border-slate-800 text-gray-500 dark:text-slate-400 font-sans">
              <tr>
                {user?.role !== "viewer" && (
                  <th className="px-4 py-4 font-medium w-8 text-center">
                    <input
                      type="checkbox"
                      className="rounded border-slate-300 text-indigo-600 focus:ring-indigo-500"
                      checked={filteredCustomers.length > 0 && filteredCustomers.every((c) => selectedIds[c.id])}
                      onChange={(e) => handleToggleSelectAll(e.target.checked)}
                      aria-label="Pilih semua pelanggan"
                    />
                  </th>
                )}
                {renderSortableHeader("Nama", "name")}
                {renderSortableHeader("Paket", "package_name")}
                {renderSortableHeader("Jatuh Tempo", "due_day")}
                {renderSortableHeader("Billing Status / Detail", "billing_lifecycle")}
                {renderSortableHeader("ODP", "odp_name")}
                {renderSortableHeader("Diskon", "diskon")}
                {renderSortableHeader("Reward Ref", "referral_balance")}
                {renderSortableHeader("Kode Ref", "referral_code")}
                {renderSortableHeader("Referred By", "referred_by_name")}
                {renderSortableHeader("Status Layanan", "status", "center")}
                {renderSortableHeader("WhatsApp", "whatsapp")}
                <th className="px-4 py-4 font-semibold text-center select-none">Aksi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200">
              {sortedCustomers.length === 0 ? (
                <EmptyTableRow
                  message={
                    customers.length === 0
                      ? "Belum ada pelanggan terdaftar."
                      : "Tidak ada pelanggan yang cocok dengan filter role saat ini."
                  }
                  colSpan={user?.role !== "viewer" ? 13 : 12}
                />
              ) : (
                sortedCustomers.map((customer) => {
                  const isMultiAccount = customer.whatsapp && customers.filter(c => {
                    if (!c.whatsapp) return false;
                    const p1 = c.whatsapp.trim().replace(/[+\-\s]/g, "").replace(/^0/, "62");
                    const p2 = customer.whatsapp.trim().replace(/[+\-\s]/g, "").replace(/^0/, "62");
                    return p1 === p2;
                  }).length > 1;

                  return (
                    <tr key={customer.id} className="hover:bg-slate-50/55 dark:hover:bg-slate-800/40 transition-colors">
                      {user?.role !== "viewer" && (
                        <td className="px-4 py-4 text-center">
                          <input
                            type="checkbox"
                            className="rounded border-slate-300 text-indigo-600 focus:ring-indigo-500"
                            checked={!!selectedIds[customer.id]}
                            onChange={(e) => handleToggleSelectOne(customer.id, e.target.checked)}
                            aria-label={`Pilih ${customer.name}`}
                          />
                        </td>
                      )}
                      <td className="px-4 py-4 font-semibold text-slate-900 dark:text-slate-50 dark:text-slate-100">
                        <div className="flex items-center gap-1.5">
                          <Button
                            variant="link"
                            type="button"
                            onClick={() => handleOpenDetails(customer)}
                            className="px-0 py-0 h-auto text-indigo-600 hover:text-indigo-700 font-semibold text-left transition-colors"
                          >
                            {customer.name}
                          </Button>
                          {isMultiAccount && (
                            <span className="inline-flex items-center px-1.5 py-0.5 rounded-md text-[10px] font-bold bg-indigo-50 text-indigo-700 border border-indigo-100 shrink-0">
                              Multi-Akun
                            </span>
                          )}
                        </div>
                      </td>
                    <td className="px-4 py-4 text-slate-700 dark:text-slate-300 font-medium">{customer.package_name ?? "-"}</td>
                    <td className="px-4 py-4 text-slate-600 dark:text-slate-400">Tgl {customer.due_day}</td>
                    <td className="px-4 py-4 text-gray-700 dark:text-slate-300">
                      <div className="flex flex-col items-start gap-1">
                        <StatusPill
                          label={customerLifecycleMap[customer.id]?.label ?? "Lunas"}
                          tone={customerLifecycleMap[customer.id]?.tone ?? "green"}
                        />
                        <span className="block text-[11px] text-slate-500 dark:text-slate-400 max-w-[260px] leading-relaxed break-words whitespace-normal font-sans">
                          {customerLifecycleMap[customer.id]?.note ?? "Tidak ada tagihan aktif."}
                        </span>
                      </div>
                    </td>
                    <td className="px-4 py-4 text-slate-700 dark:text-slate-300 font-medium">{customer.odp_name || "-"}</td>
                    <td className="px-4 py-4 text-slate-700 dark:text-slate-300 font-semibold">
                      {customer.diskon > 0 ? (customer.tipe_diskon === "percent" ? `${customer.diskon}%` : `Rp ${customer.diskon.toLocaleString("id-ID")}`) : "-"}
                    </td>
                    <td className="px-4 py-4 text-slate-700 dark:text-slate-300 font-semibold">
                      {customer.referral_balance > 0 ? `Rp ${customer.referral_balance.toLocaleString("id-ID")}` : "-"}
                    </td>
                    <td className="px-4 py-4 text-slate-750 dark:text-slate-300 font-mono text-xs">{customer.referral_code || "-"}</td>
                    <td className="px-4 py-4 text-slate-600 dark:text-slate-400 font-semibold">{customer.referred_by_name || "-"}</td>
                    <td className="px-4 py-4 text-center">
                      <select
                        className="bg-white dark:bg-slate-900 border border-slate-250 dark:border-slate-800 text-slate-750 dark:text-slate-200 text-xs rounded-lg px-2.5 py-1 focus:outline-none focus:ring-1 focus:ring-indigo-500 transition-colors"
                        value={customer.status}
                        onChange={(e) => onStatusChange(customer.id, e.target.value as CustomerItem["status"])}
                      >
                        <option value="active">Active</option>
                        <option value="limit">Limit</option>
                        <option value="suspended">Suspended</option>
                        <option value="inactive">Inactive</option>
                        <option value="wifi_umum">WiFi Umum</option>
                      </select>
                    </td>
                    <td className="px-4 py-4 text-slate-700 dark:text-slate-300">
                      {customer.whatsapp ? (
                        <a
                          href={`https://wa.me/+${customer.whatsapp.replace(/[+\-\s]/g, "").replace(/^0/, "62")}`}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-indigo-600 hover:text-indigo-700 dark:text-indigo-400 dark:hover:text-indigo-300 hover:underline font-mono text-xs font-semibold"
                        >
                          {customer.whatsapp}
                        </a>
                      ) : (
                        "-"
                      )}
                    </td>
                    <td className="px-4 py-4 text-center">
                      {user?.role !== "viewer" && (
                        <div className="flex items-center justify-center gap-2">
                          <Button
                            type="button"
                            variant="outline"
                            size="sm"
                            className="bg-white dark:bg-slate-900 border-slate-200 dark:border-slate-800 hover:bg-slate-50 dark:hover:bg-slate-800/40 text-slate-700 dark:text-slate-300"
                            onClick={() => {
                              onEdit(customer);
                              onSetFormOpen(true);
                            }}
                          >
                            Edit
                          </Button>
                          <Button
                            type="button"
                            variant="danger"
                            size="sm"
                            className="bg-red-50 border-red-200 text-red-600 hover:bg-red-100"
                            onClick={() => onDelete(customer.id)}
                          >
                            Hapus
                          </Button>
                        </div>
                      )}
                    </td>
                  </tr>
                );
              })
            )}
            </tbody>
          </table>
        </div>
      </article>

      {/* Broadcast WhatsApp Overlay Modal */}
      <BroadcastModal
        isOpen={isBroadcastOpen}
        onClose={() => setIsBroadcastOpen(false)}
