                      </option>
                    ))}
                  </datalist>
                </label>
              </div>
            </div>
          </form>
        </Modal>
      )}
    </section>
  );
}

function formatWhatsAppNumber(val: string): string {
  let clean = val.replace(/[^\d+]/g, "");
  
  if (clean.startsWith("+62")) {
    clean = "62" + clean.slice(3);
  }
  
  if (/^[89]/.test(clean)) {
    clean = "0" + clean;
  }

  if (clean.startsWith("62")) {
    const rest = clean.slice(2).replace(/\D/g, "");
    let formatted = "+62";
    if (rest.length > 0) {
      formatted += " ";
      if (rest.length <= 3) {
        formatted += rest;
      } else if (rest.length <= 7) {
        formatted += `${rest.slice(0, 3)}-${rest.slice(3)}`;
      } else {
        formatted += `${rest.slice(0, 3)}-${rest.slice(3, 7)}-${rest.slice(7, 12)}`;
      }
    }
    return formatted;
  } else if (clean.startsWith("0")) {
    const rest = clean.slice(1).replace(/\D/g, "");
    let formatted = "0";
    if (rest.length > 0) {
      if (rest.length <= 3) {
        formatted += rest;
      } else if (rest.length <= 7) {
        formatted += `${rest.slice(0, 3)}-${rest.slice(3)}`;
      } else {
        formatted += `${rest.slice(0, 3)}-${rest.slice(3, 7)}-${rest.slice(7, 12)}`;
      }
    }
    return formatted;
  }
  return clean;
}

