function formatCurrencyShort(value: number): string {
  if (value === 0) return "Rp 0k";
  if (value >= 1000000) {
    const val = value / 1000000;
    return `Rp ${Number(val.toFixed(1))}jt`;
  }
  if (value >= 1000) {
    const val = value / 1000;
    return `Rp ${Number(val.toFixed(0))}k`;
  }
  return `Rp ${value}`;
}

