                          className="!py-2 !px-3 !rounded-l-none !rounded-r-xl border border-l-0 border-slate-200 dark:border-slate-800 dark:border-slate-700 bg-slate-50 dark:bg-slate-950 dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700"
