                      ) : (
                        <p className="text-[10px] text-slate-400 dark:text-slate-500 text-center py-3 italic border-t border-slate-50 dark:border-slate-800 pt-3">
                          Klik Cek untuk memindai status optical power ONT.
                        </p>
                      )}
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        )}
      </article>

      {/* Manual Ticket Creation Modal */}
      {isCreateModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 w-full max-w-md rounded-card shadow-xl flex flex-col overflow-hidden animate-in zoom-in-95 duration-200">
            {/* Header */}
            <div className="p-5 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-slate-50/50 dark:bg-slate-950/20">
              <div>
                <h3 className="text-xs font-bold text-slate-900 dark:text-slate-50 dark:text-white uppercase tracking-wider font-sans">Tambah Tiket Baru</h3>
                <p className="text-[10px] text-slate-450 mt-0.5">Laporkan kendala support baru secara manual.</p>
              </div>
              <Button
                type="button"
                variant="ghost"
                onClick={() => setIsCreateModalOpen(false)}
                className="!p-1 text-slate-400 dark:text-slate-500 hover:text-slate-600 dark:hover:text-slate-350"
              >
                <X size={16} />
              </Button>
            </div>

            {/* Content Form */}
            <form onSubmit={handleCreateTicketSubmit} className="p-5 flex flex-col gap-3.5">
              <label className="flex flex-col gap-1">
                <span className="text-xs font-bold text-slate-700 dark:text-slate-300 dark:text-slate-350">Hubungkan ke Pelanggan</span>
                <select
                  className="w-full text-xs px-3 py-2.5 border rounded-xl bg-white dark:bg-slate-900 dark:bg-slate-800 text-slate-800 dark:text-slate-100 dark:text-slate-300 focus:ring-2 focus:ring-indigo-500"
                  value={selectedCustomerIdForTicket || ""}
                  onChange={(e) => {
                    const val = e.target.value;
                    handleSelectCustomerForTicket(val ? Number(val) : null);
                  }}
                >
                  <option value="">-- Input Manual / Pelanggan Baru --</option>
                  {loadingCustomers ? (
                    <option disabled>Loading data pelanggan...</option>
                  ) : (
                    customersList.map((c) => (
                      <option key={c.id} value={c.id}>
                        {c.name} ({c.user_pppoe || "Tanpa PPPoE"})
                      </option>
                    ))
                  )}
                </select>
              </label>

              <div className="grid grid-cols-2 gap-3">
                <label className="flex flex-col gap-1">
                  <span className="text-xs font-bold text-slate-700 dark:text-slate-300 dark:text-slate-350">Nama Pelapor</span>
                  <input
                    type="text"
                    required
                    className="w-full text-xs px-3 py-2 border rounded-xl bg-white dark:bg-slate-900 dark:bg-slate-800 text-slate-800 dark:text-slate-100 dark:text-slate-300 focus:ring-2 focus:ring-indigo-500 disabled:opacity-60"
                    value={newTicketNama}
                    onChange={(e) => setNewTicketNama(e.target.value)}
                    placeholder="Budi Santoso"
                    disabled={selectedCustomerIdForTicket !== null}
                  />
                </label>
                <label className="flex flex-col gap-1">
                  <span className="text-xs font-bold text-slate-700 dark:text-slate-300 dark:text-slate-350">No WhatsApp</span>
                  <input
                    type="text"
                    required
                    className="w-full text-xs px-3 py-2 border rounded-xl bg-white dark:bg-slate-900 dark:bg-slate-800 text-slate-800 dark:text-slate-100 dark:text-slate-300 focus:ring-2 focus:ring-indigo-500 disabled:opacity-60"
                    value={newTicketNoHP}
                    onChange={(e) => setNewTicketNoHP(e.target.value)}
                    placeholder="Contoh: 628123456789"
                    disabled={selectedCustomerIdForTicket !== null}
                  />
                </label>
              </div>

              <label className="flex flex-col gap-1">
                <span className="text-xs font-bold text-slate-700 dark:text-slate-300 dark:text-slate-350">Alamat Lengkap</span>
                <input
                  type="text"
                  className="w-full text-xs px-3 py-2 border rounded-xl bg-white dark:bg-slate-900 dark:bg-slate-800 text-slate-800 dark:text-slate-100 dark:text-slate-300 focus:ring-2 focus:ring-indigo-500 disabled:opacity-60"
                  value={newTicketAlamat}
                  onChange={(e) => setNewTicketAlamat(e.target.value)}
                  placeholder="Jl. Melati No. 12"
                  disabled={selectedCustomerIdForTicket !== null}
                />
              </label>

              <label className="flex flex-col gap-1">
                <span className="text-xs font-bold text-slate-700 dark:text-slate-300 dark:text-slate-350">Detail Kendala</span>
                <textarea
                  required
                  rows={3}
                  className="w-full text-xs px-3 py-2 border rounded-xl bg-white dark:bg-slate-900 dark:bg-slate-800 text-slate-800 dark:text-slate-100 dark:text-slate-300 focus:ring-2 focus:ring-indigo-500"
                  value={newTicketKendala}
                  onChange={(e) => setNewTicketKendala(e.target.value)}
                  placeholder="Deskripsikan masalah perangkat/koneksi pelanggan..."
                />
              </label>

              <div className="flex justify-end gap-2.5 mt-3 border-t border-slate-100 dark:border-slate-800 pt-4">
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => setIsCreateModalOpen(false)}
                >
                  Batal
                </Button>
                <Button
                  type="submit"
                  variant="primary"
                  disabled={creatingTicket}
                  isLoading={creatingTicket}
                  loadingText="Membuat..."
                >
                  Buat Tiket
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}
    </section>
  );
}

import { useState, useEffect, useMemo } from "react";
import { Line } from "react-chartjs-2";
import { Search, Activity, ArrowUp, ArrowDown, X, Info, ChevronUp, ChevronDown, ArrowUpDown } from "lucide-react";
import type { CustomerItem, PackageItem } from "../../types";
import { fetchTrafficStats, type TrafficStats } from "../../lib/api";
import { Button } from "../../components/ui/Button";

type TrafficPageProps = {
  customers: CustomerItem[];
  packages: PackageItem[];
};

type HistoryPoint = {
  time: string;
  tx: number; // in Mbps
  rx: number; // in Mbps
};

function formatBps(bps: number): string {
  if (!bps || bps <= 0) return "0 bps";
  if (bps >= 1000000000) {
    return `${(bps / 1000000000).toFixed(2)} Gbps`;
  }
  if (bps >= 1000000) {
    return `${(bps / 1000000).toFixed(2)} Mbps`;
  }
  if (bps >= 1000) {
    return `${(bps / 1000).toFixed(1)} Kbps`;
  }
  return `${bps} bps`;
}

export function TrafficPage({ customers, packages }: TrafficPageProps) {
  const [searchTerm, setSearchTerm] = useState("");
  const [trafficData, setTrafficData] = useState<Record<string, TrafficStats>>({});
  const [selectedCust, setSelectedCust] = useState<CustomerItem | null>(null);
  const [history, setHistory] = useState<HistoryPoint[]>([]);

  const [sortField, setSortField] = useState<string | null>("usagePercent");
  const [sortDirection, setSortDirection] = useState<"asc" | "desc">("desc");

  const requestSort = (field: string) => {
    if (sortField === field) {
      setSortDirection((prev) => (prev === "asc" ? "desc" : "asc"));
    } else {
      setSortField(field);
      setSortDirection("asc");
    }
  };

  const renderSortableHeader = (label: string, field: string, align: "left" | "center" = "left") => {
    const isSorted = sortField === field;
    return (
      <th 
        className={`px-6 py-4 font-semibold select-none cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors text-slate-550 dark:text-slate-400 ${align === "center" ? "text-center" : "text-left"}`}
        onClick={() => requestSort(field)}
      >
        <div className={`inline-flex items-center gap-1.5 ${align === "center" ? "justify-center w-full" : ""}`}>
          <span>{label}</span>
          {isSorted ? (
            sortDirection === "asc" ? (
              <ChevronUp size={12} className="text-indigo-600 dark:text-indigo-400 stroke-[3]" />
            ) : (
              <ChevronDown size={12} className="text-indigo-600 dark:text-indigo-400 stroke-[3]" />
            )
          ) : (
            <ArrowUpDown size={12} className="text-slate-300 dark:text-slate-600 opacity-50 transition-opacity" />
          )}
        </div>
      </th>
    );
  };

  // Polling loop for traffic stats (every 2.5s)
  useEffect(() => {
    let active = true;

    async function poll() {
      try {
        const res = await fetchTrafficStats();
        if (active && res && res.data) {
          setTrafficData(res.data);

          // If a modal is open, append the new statistics to the chart history
          if (selectedCust) {
            const username = selectedCust.user_pppoe.toLowerCase();
            const stats = res.data[username] || { tx_rate: 0, rx_rate: 0 };
            
            const nowTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
            const newPoint: HistoryPoint = {
              time: nowTime,
              tx: stats.tx_rate / 1000000, // convert to Mbps
              rx: stats.rx_rate / 1000000, // convert to Mbps
            };

            setHistory((prev) => {
              const next = [...prev, newPoint];
              if (next.length > 24) { // keep 60 seconds of history (24 * 2.5s)
                next.shift();
              }
              return next;
            });
          }
        }
      } catch (err) {
        console.error("Gagal mengambil status traffic", err);
      }
    }

    // Run once immediately
    void poll();

    const interval = setInterval(() => {
      void poll();
    }, 2500);

    return () => {
      active = false;
      clearInterval(interval);
    };
  }, [selectedCust]);

  // Open modal and prepopulate history
  const handleOpenDetails = (cust: CustomerItem) => {
    setSelectedCust(cust);
    const now = new Date();
    const initialHistory: HistoryPoint[] = [];
    const username = cust.user_pppoe.toLowerCase();
    const stats = trafficData[username] || { tx_rate: 0, rx_rate: 0 };

    for (let i = 9; i >= 0; i--) {
      const timeStr = new Date(now.getTime() - i * 2500).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
      initialHistory.push({
        time: timeStr,
        tx: stats.tx_rate / 1000000,
        rx: stats.rx_rate / 1000000,
      });
    }
    setHistory(initialHistory);
  };

  const handleCloseDetails = () => {
    setSelectedCust(null);
    setHistory([]);
  };

  // Helper to resolve speed limit of customer package
  const getCustomerPackageSpeed = (cust: CustomerItem) => {
    const pkg = packages.find((p) => p.id === cust.package_id);
    return pkg ? pkg.speed_mbps : 10; // default to 10 Mbps
  };

  // Filter PPPoE active customers
  const activeCustomers = useMemo(() => {
    return customers.filter(c => c.user_pppoe && c.status !== "inactive");
  }, [customers]);

  const filteredCustomers = useMemo(() => {
    return activeCustomers.filter((c) => {
      const term = searchTerm.toLowerCase();
      return (
        c.name.toLowerCase().includes(term) ||
        c.user_pppoe.toLowerCase().includes(term) ||
        (c.package_name && c.package_name.toLowerCase().includes(term))
      );
    });
  }, [activeCustomers, searchTerm]);

  // Threshold computations for row styling and statistics
  const processedCustomers = useMemo(() => {
    return filteredCustomers.map((cust) => {
      const username = cust.user_pppoe.toLowerCase();
      const stats = trafficData[username] || { tx_rate: 0, rx_rate: 0 };
      const limitMbps = getCustomerPackageSpeed(cust);
      const limitBps = limitMbps * 1000000;

      // Rx (Download) is Tx from router perspective, Tx (Upload) is Rx from router perspective.
      // Already reversed inside backend poller, so tx_rate is customer Upload and rx_rate is customer Download.
      const maxRate = Math.max(stats.rx_rate, stats.tx_rate);
      const usagePercent = limitBps > 0 ? (maxRate / limitBps) * 100 : 0;

      let statusColor = "text-slate-500 dark:text-slate-400";
      let statusBg = "bg-slate-100 dark:bg-slate-900";
      let statusText = "Normal";
      let isWarning = false;
      let isCritical = false;

      if (usagePercent >= 100) {
        statusColor = "text-rose-600 dark:text-rose-400 font-bold";
        statusBg = "bg-rose-50 dark:bg-rose-950/40 border border-rose-200 dark:border-rose-900/60";
        statusText = "Over Limit";
        isCritical = true;
      } else if (usagePercent >= 90) {
        statusColor = "text-amber-600 dark:text-amber-400 font-semibold";
        statusBg = "bg-amber-50 dark:bg-amber-950/40 border border-amber-200 dark:border-amber-900/60";
        statusText = "Near Limit";
        isWarning = true;
      }

      return {
        ...cust,
        stats,
        limitMbps,
        usagePercent,
        statusColor,
        statusBg,
        statusText,
        isWarning,
        isCritical,
      };
    });
  }, [filteredCustomers, trafficData, packages]);

  const sortedCustomers = useMemo(() => {
    const list = processedCustomers;
    if (!sortField) return list;
    return [...list].sort((a, b) => {
      let aVal: any = null;
      let bVal: any = null;

      if (sortField === "rx_rate") {
        aVal = a.stats?.rx_rate || 0;
        bVal = b.stats?.rx_rate || 0;
      } else if (sortField === "tx_rate") {
        aVal = a.stats?.tx_rate || 0;
        bVal = b.stats?.tx_rate || 0;
      } else {
        aVal = (a as any)[sortField];
        bVal = (b as any)[sortField];
      }

      const isNumericField = sortField === "limitMbps" || sortField === "usagePercent" || sortField === "rx_rate" || sortField === "tx_rate";
      if (aVal === null || aVal === undefined) aVal = isNumericField ? 0 : "";
      if (bVal === null || bVal === undefined) bVal = isNumericField ? 0 : "";

      if (isNumericField) {
        return sortDirection === "asc" ? aVal - bVal : bVal - aVal;
      }

      const aStr = String(aVal).trim().toLowerCase();
      const bStr = String(bVal).trim().toLowerCase();
      return sortDirection === "asc"
        ? aStr.localeCompare(bStr, undefined, { numeric: true, sensitivity: "base" })
        : bStr.localeCompare(aStr, undefined, { numeric: true, sensitivity: "base" });
    });
  }, [processedCustomers, sortField, sortDirection]);

  // Overall page stats
  const totals = useMemo(() => {
    let totalTx = 0;
    let totalRx = 0;
    let overLimitCount = 0;
    let nearLimitCount = 0;

    activeCustomers.forEach((cust) => {
      const username = cust.user_pppoe.toLowerCase();
      const stats = trafficData[username] || { tx_rate: 0, rx_rate: 0 };
      const limitMbps = getCustomerPackageSpeed(cust);
      const limitBps = limitMbps * 1000000;

      totalTx += stats.tx_rate;
      totalRx += stats.rx_rate;

      const maxRate = Math.max(stats.rx_rate, stats.tx_rate);
      const percent = limitBps > 0 ? (maxRate / limitBps) * 100 : 0;

      if (percent >= 100) {
        overLimitCount++;
      } else if (percent >= 90) {
        nearLimitCount++;
      }
    });

    return {
      tx: totalTx,
      rx: totalRx,
      overLimit: overLimitCount,
      nearLimit: nearLimitCount,
      activeUsers: activeCustomers.length,
    };
  }, [activeCustomers, trafficData, packages]);

  // Chart data for selected user modal
  const chartData = useMemo(() => {
    return {
      labels: history.map((h) => h.time),
      datasets: [
        {
          label: "Download (Rx)",
          data: history.map((h) => h.rx),
          borderColor: "rgba(99, 102, 241, 1)",
          backgroundColor: "rgba(99, 102, 241, 0.08)",
          fill: true,
          borderWidth: 2,
          tension: 0.4,
          pointRadius: 0,
        },
        {
          label: "Upload (Tx)",
          data: history.map((h) => h.tx),
          borderColor: "rgba(236, 72, 153, 1)",
          backgroundColor: "rgba(236, 72, 153, 0.08)",
          fill: true,
          borderWidth: 2,
          tension: 0.4,
          pointRadius: 0,
        },
      ],
    };
  }, [history]);

  // Modal active user details
  const activeStats = selectedCust ? trafficData[selectedCust.user_pppoe.toLowerCase()] || { tx_rate: 0, rx_rate: 0 } : null;
  const activeLimit = selectedCust ? getCustomerPackageSpeed(selectedCust) : 10;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-xl font-extrabold text-slate-800 dark:text-slate-100">Traffic Monitor</h2>
          <p className="text-xs text-slate-500 dark:text-slate-400">Pantau Tx/Rx real-time seluruh koneksi PPPoE aktif.</p>
        </div>
        
        {/* Search Bar */}
        <div className="relative w-full md:w-80">
          <span className="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none">
            <Search className="h-4 w-4 text-slate-400 dark:text-slate-500" />
          </span>
          <input
            type="text"
            placeholder="Cari nama, PPPoE, atau paket..."
            className="w-full pl-10 pr-4 py-2 text-sm bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 dark:border-slate-850 rounded-xl focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent text-slate-800 dark:text-slate-100 dark:text-slate-200"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      {/* Summary Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-4">
        <div className="bg-white dark:bg-slate-900 dark:bg-slate-900/60 border border-slate-200 dark:border-slate-800 dark:border-slate-800/80 p-5 rounded-card shadow-sm flex items-center gap-4">
          <div className="w-11 h-11 bg-indigo-50 dark:bg-indigo-950/40 rounded-xl flex items-center justify-center text-indigo-600 dark:text-indigo-400 shrink-0">
            <Activity size={20} />
          </div>
          <div>
            <span className="block text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider">Aktif PPPoE</span>
            <strong className="text-lg font-extrabold text-slate-800 dark:text-slate-100 dark:text-slate-200">{totals.activeUsers} User</strong>
          </div>
        </div>

        <div className="bg-white dark:bg-slate-900 dark:bg-slate-900/60 border border-slate-200 dark:border-slate-800 dark:border-slate-800/80 p-5 rounded-card shadow-sm flex items-center gap-4">
          <div className="w-11 h-11 bg-emerald-50 dark:bg-emerald-950/40 rounded-xl flex items-center justify-center text-emerald-600 dark:text-emerald-400 shrink-0">
            <ArrowDown size={20} />
          </div>
          <div>
            <span className="block text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider">Total Download (Rx)</span>
            <strong className="text-lg font-extrabold text-emerald-600 dark:text-emerald-400">{formatBps(totals.rx)}</strong>
          </div>
        </div>

        <div className="bg-white dark:bg-slate-900 dark:bg-slate-900/60 border border-slate-200 dark:border-slate-800 dark:border-slate-800/80 p-5 rounded-card shadow-sm flex items-center gap-4">
          <div className="w-11 h-11 bg-pink-50 dark:bg-pink-950/40 rounded-xl flex items-center justify-center text-pink-600 dark:text-pink-400 shrink-0">
            <ArrowUp size={20} />
          </div>
          <div>
            <span className="block text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider">Total Upload (Tx)</span>
            <strong className="text-lg font-extrabold text-pink-600 dark:text-pink-400">{formatBps(totals.tx)}</strong>
          </div>
        </div>

        <div className="bg-white dark:bg-slate-900 dark:bg-slate-900/60 border border-slate-200 dark:border-slate-800 dark:border-slate-800/80 p-5 rounded-card shadow-sm flex items-center gap-4">
          <div className="w-11 h-11 bg-amber-50 dark:bg-amber-950/40 rounded-xl flex items-center justify-center text-amber-600 dark:text-amber-400 shrink-0">
            <Info size={20} />
          </div>
          <div>
            <span className="block text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider">Mendekati Limit (&ge;90%)</span>
            <strong className="text-lg font-extrabold text-amber-600 dark:text-amber-400">{totals.nearLimit} User</strong>
          </div>
        </div>

        <div className="bg-white dark:bg-slate-900 dark:bg-slate-900/60 border border-slate-200 dark:border-slate-800 dark:border-slate-800/80 p-5 rounded-card shadow-sm flex items-center gap-4">
          <div className="w-11 h-11 bg-rose-50 dark:bg-rose-950/40 rounded-xl flex items-center justify-center text-rose-600 dark:text-rose-400 shrink-0">
            <Info size={20} />
          </div>
          <div>
            <span className="block text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider">Melebihi Limit (&ge;100%)</span>
            <strong className="text-lg font-extrabold text-rose-600 dark:text-rose-400">{totals.overLimit} User</strong>
          </div>
        </div>
      </div>

      {/* Main Customers Traffic Table */}
      <div className="bg-white dark:bg-slate-900 dark:bg-slate-900/40 border border-slate-200 dark:border-slate-800 dark:border-slate-850 rounded-card shadow-sm overflow-hidden backdrop-blur-md">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse text-sm">
            <thead className="bg-slate-55/60 dark:bg-slate-950/80 border-b border-slate-200 dark:border-slate-800 dark:border-slate-850/80 text-slate-500 dark:text-slate-400 text-xs uppercase font-extrabold tracking-wider">
              <tr>
                {renderSortableHeader("Nama Pelanggan", "name")}
                {renderSortableHeader("PPPoE Username", "user_pppoe")}
                {renderSortableHeader("Paket / Profil", "package_name")}
                {renderSortableHeader("Limit Kecepatan", "limitMbps")}
                {renderSortableHeader("Download (Rx)", "rx_rate")}
                {renderSortableHeader("Upload (Tx)", "tx_rate")}
                {renderSortableHeader("Utilisasi", "usagePercent")}
                <th className="px-6 py-4 font-semibold text-center text-slate-500 dark:text-slate-400">Status</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-850/40">
              {sortedCustomers.length === 0 ? (
                <tr>
                  <td colSpan={8} className="px-6 py-12 text-center text-slate-400 dark:text-slate-500">
                    Tidak ada pelanggan PPPoE aktif yang cocok dengan pencarian.
                  </td>
                </tr>
              ) : (
                sortedCustomers.map((cust) => {
                  const isRed = cust.isCritical;
                  const isYellow = cust.isWarning;

                  return (
                    <tr
                      key={cust.id}
                      onClick={() => handleOpenDetails(cust)}
                      className={`hover:bg-slate-50/60 dark:hover:bg-slate-800/40 cursor-pointer transition-colors duration-150 ${
                        isRed
                          ? "bg-rose-50/20 hover:bg-rose-50/40 dark:bg-rose-950/10 dark:hover:bg-rose-950/20"
                          : isYellow
                            ? "bg-amber-50/20 hover:bg-amber-50/40 dark:bg-amber-950/10 dark:hover:bg-amber-950/20"
                            : ""
                      }`}
                    >
                      <td className="px-6 py-4 font-bold text-slate-800 dark:text-slate-100 dark:text-slate-200">{cust.name}</td>
                      <td className="px-6 py-4 text-slate-500 dark:text-slate-400 font-mono text-xs">{cust.user_pppoe}</td>
                      <td className="px-6 py-4 text-slate-500 dark:text-slate-400">{cust.package_name || "-"}</td>
                      <td className="px-6 py-4 font-semibold text-slate-700 dark:text-slate-300 dark:text-slate-350">
                        {cust.limitMbps === 0 ? "Bypass" : `${cust.limitMbps} Mbps`}
                      </td>
                      <td className={`px-6 py-4 font-bold ${isRed ? "text-rose-600 dark:text-rose-450" : isYellow ? "text-amber-600 dark:text-amber-450" : "text-emerald-600 dark:text-emerald-450"}`}>
                        {formatBps(cust.stats.rx_rate)}
                      </td>
                      <td className={`px-6 py-4 font-bold ${isRed ? "text-rose-600 dark:text-rose-450" : isYellow ? "text-amber-600 dark:text-amber-450" : "text-pink-600 dark:text-pink-450"}`}>
                        {formatBps(cust.stats.tx_rate)}
                      </td>
                      <td className="px-6 py-4 w-40">
                        <div className="flex items-center gap-2">
                          <div className="flex-1 h-2 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                            <div
                              className={`h-full rounded-full transition-all duration-300 ${
                                isRed
                                  ? "bg-rose-500"
                                  : isYellow
                                    ? "bg-amber-500"
                                    : "bg-indigo-500"
                              }`}
                              style={{ width: `${Math.min(cust.usagePercent, 100)}%` }}
                            />
                          </div>
                          <span className={`text-[11px] font-bold shrink-0 ${isRed ? "text-rose-600" : isYellow ? "text-amber-600" : "text-slate-500 dark:text-slate-400"}`}>
                            {cust.usagePercent.toFixed(0)}%
                          </span>
                        </div>
                      </td>
                      <td className="px-6 py-4 text-center">
                        <span className={`inline-block px-3 py-1 rounded-full text-[10px] uppercase font-bold leading-none ${cust.statusBg} ${cust.statusColor}`}>
                          {cust.statusText}
                        </span>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Real-time statistics modal chart */}
      {selectedCust && activeStats && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4 transition-all duration-300 fade-in">
          <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-card shadow-2xl w-full max-w-3xl overflow-hidden transform scale-in">
            {/* Modal Header */}
            <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between">
              <div>
                <span className="inline-block bg-indigo-50 dark:bg-indigo-950/40 text-indigo-600 dark:text-indigo-400 text-[10px] font-bold uppercase tracking-wider px-2.5 py-1 rounded-lg mb-1.5">
                  Statistik Real-Time
                </span>
                <h3 className="text-lg font-extrabold text-slate-850 dark:text-slate-100">
                  {selectedCust.name}
                </h3>
                <p className="text-xs text-slate-400 dark:text-slate-500 font-mono mt-0.5">
                  PPPoE User: {selectedCust.user_pppoe} ÔÇó Limit: {activeLimit === 0 ? "Bypass" : `${activeLimit} Mbps`}
                </p>
              </div>
              <Button
                type="button"
                variant="ghost"
                onClick={handleCloseDetails}
                className="w-8 h-8 rounded-full p-0 flex items-center justify-center bg-slate-50 dark:bg-slate-950 dark:bg-slate-800 text-slate-400 dark:text-slate-500 hover:text-slate-600 dark:hover:text-slate-300"
              >
                <X size={16} />
              </Button>
            </div>

            {/* Modal Body */}
            <div className="p-6 space-y-6">
              {/* Active Badges */}
              <div className="grid grid-cols-2 gap-4">
                <div className="bg-slate-50 dark:bg-slate-950 p-4 rounded-xl border border-slate-100 dark:border-slate-800 dark:border-slate-850 flex items-center gap-3">
                  <div className="w-9 h-9 rounded-lg bg-emerald-50 dark:bg-emerald-950/40 text-emerald-600 dark:text-emerald-400 flex items-center justify-center shrink-0">
                    <ArrowDown size={18} />
                  </div>
                  <div>
                    <span className="block text-[9px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider">Download</span>
                    <strong className="text-base font-extrabold text-emerald-600 dark:text-emerald-400">
                      {formatBps(activeStats.rx_rate)}
                    </strong>
                  </div>
                </div>

                <div className="bg-slate-50 dark:bg-slate-950 p-4 rounded-xl border border-slate-100 dark:border-slate-800 dark:border-slate-850 flex items-center gap-3">
                  <div className="w-9 h-9 rounded-lg bg-pink-50 dark:bg-pink-950/40 text-pink-600 dark:text-pink-400 flex items-center justify-center shrink-0">
                    <ArrowUp size={18} />
                  </div>
                  <div>
                    <span className="block text-[9px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider">Upload</span>
                    <strong className="text-base font-extrabold text-pink-600 dark:text-pink-400">
                      {formatBps(activeStats.tx_rate)}
                    </strong>
                  </div>
                </div>
              </div>

              {/* Line Chart */}
              <div className="h-72 border border-slate-100 dark:border-slate-800 dark:border-slate-850 p-3 rounded-xl bg-slate-50/50 dark:bg-slate-950/30">
                <Line
                  data={chartData}
                  options={{
                    responsive: true,
                    maintainAspectRatio: false,
                    animation: { duration: 0 }, // disable chart.js standard anims to make updates snappy
                    plugins: {
                      legend: { position: "bottom", labels: { boxWidth: 12, font: { size: 10 } } },
                      tooltip: {
                        cornerRadius: 8,
                        callbacks: {
                          label: (context: any) => {
                            const val = context.parsed.y || 0;
                            return ` ${context.dataset.label}: ${val.toFixed(2)} Mbps`;
                          }
                        }
                      }
                    },
                    scales: {
                      y: {
                        beginAtZero: true,
                        title: { display: true, text: "Bandwidth (Mbps)", font: { size: 10 } },
                        grid: {
                          color: () => document.documentElement.classList.contains("dark")
                            ? "rgba(51, 65, 85, 0.3)"
                            : "rgba(241, 245, 249, 1)"
                        }
                      },
                      x: {
                        grid: { display: false },
                        ticks: { maxTicksLimit: 6, font: { size: 9 } }
                      }
                    }
                  }}
                />
              </div>
            </div>

            {/* Modal Footer */}
            <div className="bg-slate-55 dark:bg-slate-950 px-6 py-4 border-t border-slate-200 dark:border-slate-800 flex justify-end">
              <Button
                type="button"
                variant="outline"
                onClick={handleCloseDetails}
              >
                Tutup
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import type { FormEvent } from "react";
import { Button } from "../../components/ui/Button";
import { StatusPill, inputClassName, renderInlineError, EmptyTableRow } from "../../components/ui";
import type { ManagedUserItem } from "../../types";
import type { FieldErrors } from "../../utils/validation";

export type ManagedUserFormState = {
  username: string;
  password: "";
  role: string;
};

export const defaultManagedUserForm = (): ManagedUserFormState => ({
  username: "",
  password: "",
  role: "petugas",
});

type UsersPageProps = {
  managedUsers: ManagedUserItem[];
  managedUserForm: ManagedUserFormState;
  managedUserErrors: FieldErrors;
  submitting: boolean;
  busyAction: string | null;
  onFormChange: (updater: (current: ManagedUserFormState) => ManagedUserFormState) => void;
  onSubmit: (e: FormEvent<HTMLFormElement>) => void;
  onUpdateRole: (item: ManagedUserItem, role: string) => void;
  onUpdateStatus: (item: ManagedUserItem, isActive: boolean) => void;
  onResetPassword: (item: ManagedUserItem) => void;
};

export function UsersPage({
  managedUsers,
  managedUserForm,
  managedUserErrors,
  submitting,
  busyAction,
  onFormChange,
  onSubmit,
  onUpdateRole,
  onUpdateStatus,
  onResetPassword,
}: UsersPageProps) {
  const isBusy = (actionKey: string) => submitting && busyAction === actionKey;

  return (
    <section className="grid grid-cols-1 lg:grid-cols-2 gap-6">
      <article className="bg-white dark:bg-slate-900 border border-gray-200 dark:border-slate-800 rounded-card p-6 shadow-sm">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-lg font-bold text-slate-900 dark:text-slate-50">Tambah User Tim</h2>
        </div>
        <form className="grid grid-cols-1 md:grid-cols-2 gap-6" onSubmit={onSubmit}>
          <label>
            <span>Username</span>
            <input
              className={inputClassName(managedUserErrors.username)}
              value={managedUserForm.username}
              onChange={(e) => onFormChange((curr) => ({ ...curr, username: e.target.value }))}
            />
            {renderInlineError(managedUserErrors.username)}
          </label>
          <label>
            <span>Password Awal</span>
            <input
              className={inputClassName(managedUserErrors.password)}
              type="password"
              value={managedUserForm.password}
              onChange={(e) => onFormChange((curr) => ({ ...curr, password: e.target.value as "" }))}
            />
            {renderInlineError(managedUserErrors.password)}
          </label>
          <label>
            <span>Role</span>
            <select
              className={inputClassName()}
              value={managedUserForm.role}
              onChange={(e) => onFormChange((curr) => ({ ...curr, role: e.target.value }))}
            >
              <option value="petugas">Petugas</option>
              <option value="admin">Admin</option>
            </select>
          </label>
          <div className="flex gap-3 mt-4">
            <Button type="submit" variant="primary" disabled={submitting}>
              {isBusy("save-user") ? "Menyimpan..." : "Simpan User"}
            </Button>
          </div>
        </form>
        <div className="border-t border-slate-100 dark:border-slate-800 pt-6 mt-6">
          <p className="text-xs text-slate-400 dark:text-slate-500 leading-relaxed flex items-center gap-2">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="12" y1="16" x2="12" y2="12"></line><line x1="12" y1="8" x2="12.01" y2="8"></line></svg>
            Gunakan akun <code className="bg-slate-50 dark:bg-slate-950 px-1 rounded">petugas</code> untuk operasional harian dan sisakan <code className="bg-slate-50 dark:bg-slate-950 px-1 rounded">admin</code> hanya untuk konfigurasi dan audit.
          </p>
        </div>
      </article>

      <article className="bg-white dark:bg-slate-900 border border-gray-200 dark:border-slate-800 rounded-card p-6 shadow-sm">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-lg font-bold text-slate-900 dark:text-slate-50">Daftar User</h2>
          <StatusPill label={`${managedUsers.length} user`} tone="slate" />
        </div>
        <div className="overflow-x-auto border border-gray-200 dark:border-slate-800 rounded-card bg-white dark:bg-slate-900 shadow-sm">
          <table className="w-full text-left border-collapse text-sm">
            <thead className="bg-gray-50 dark:bg-slate-800 border-b border-gray-200 dark:border-slate-800 text-gray-500 dark:text-slate-400">
              <tr>
                <th className="px-6 py-4 font-medium">Username</th>
                <th className="px-6 py-4 font-medium">Role</th>
                <th className="px-6 py-4 font-medium">Status</th>
                <th className="px-6 py-4 font-medium">Terakhir Login</th>
                <th className="px-6 py-4 font-medium">Aksi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200">
              {managedUsers.length === 0 ? (
                <EmptyTableRow message="Belum ada user tim tambahan." colSpan={5} />
              ) : (
                managedUsers.map((item) => (
                  <tr key={item.id} className="hover:bg-gray-50 dark:hover:bg-slate-800/40 transition-colors">
                    <td className="px-6 py-4 text-gray-700 dark:text-slate-300">{item.username}</td>
                    <td className="px-6 py-4 text-gray-700 dark:text-slate-300">
                      <select
                        className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-slate-700 dark:text-slate-300 text-xs rounded-lg px-2 py-1 focus:outline-none focus:ring-1 focus:ring-indigo-500"
                        value={item.role}
                        onChange={(e) => onUpdateRole(item, e.target.value)}
                      >
                        <option value="petugas">Petugas</option>
                        <option value="admin">Admin</option>
                      </select>
                    </td>
                    <td className="px-6 py-4 text-gray-700 dark:text-slate-300">
                      <select
                        className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-slate-700 dark:text-slate-300 text-xs rounded-lg px-2 py-1 focus:outline-none focus:ring-1 focus:ring-indigo-500"
                        value={item.is_active ? "1" : "0"}
                        onChange={(e) => onUpdateStatus(item, e.target.value === "1")}
                      >
                        <option value="1">Aktif</option>
                        <option value="0">Nonaktif</option>
                      </select>
                    </td>
                    <td className="px-6 py-4 text-gray-700 dark:text-slate-300">
                      {item.last_login_at ? (
                        <div className="flex flex-col text-sm">
                          <span>{new Date(item.last_login_at).toLocaleString("id-ID")}</span>
                          <span className="muted">{item.last_login_ip || "-"}</span>
                        </div>
                      ) : (
                        <span className="muted">Belum pernah</span>
                      )}
                    </td>
                    <td className="px-6 py-4 text-gray-700 dark:text-slate-300">
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        onClick={() => onResetPassword(item)}
                      >
                        Reset Password
                      </Button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </article>
    </section>
  );
}

import { useState, useEffect, useCallback } from "react";
import { Button } from "../../components/ui/Button";
import { useWhatsAppGateway } from "../../hooks/useWhatsAppGateway";
import {
  getGatewayAccounts,
  deleteGatewayAccount,
  getGatewayAccountQr,
  getGatewayHistory,
  type GatewayAccount,
  type GatewayMessage,
  createGatewayAccount,
} from "../../lib/gatewayApi";
import { RefreshCw, Wifi, MessageSquare, ShieldAlert } from "lucide-react";
import type { User, SettingsState, TemplateItem } from "../../types";
import type { ConfirmDialogState } from "../../hooks/types";

import { AccountsTab } from "./components/AccountsTab";
import { QrTab } from "./components/QrTab";
import { HistoryTab } from "./components/HistoryTab";

type WhatsAppPageProps = {
  user: User;
  waGatewayUrl?: string;
  waAccountId?: string;
  waApiKey?: string;
  pushSuccess: (msg: string) => void;
  pushError: (msg: string) => void;
  withFeedback: (fn: () => Promise<void>, actionKey?: string) => Promise<void>;
  askForConfirmation: (config: ConfirmDialogState) => void;
  settingsForm: SettingsState;
  setSettingsForm: (form: SettingsState) => void;
  refreshSettings: () => Promise<void>;
  templates: TemplateItem[];
  refreshTemplates: () => Promise<void>;
};

type ActiveTab = "accounts" | "qr" | "history";

export function WhatsAppPage({
  user,
  waGatewayUrl,
  waAccountId,
  waApiKey,
  pushSuccess,
  pushError,
  withFeedback,
  askForConfirmation,
  settingsForm,
  setSettingsForm,
  refreshSettings,
  templates,
  refreshTemplates,
}: WhatsAppPageProps) {
  const gatewayUrl = waGatewayUrl?.trim() || "http://localhost:3001";
  const configuredAccountId = waAccountId?.trim() || "default";
  const apiKey = waApiKey?.trim() || "";

  const [activeTab, setActiveTab] = useState<ActiveTab>("accounts");
  const [qrSelectedAccountId, setQrSelectedAccountId] = useState(configuredAccountId);

  // Shared Gateway States
  const [historyMessages, setHistoryMessages] = useState<GatewayMessage[]>([]);

  const [loading, setLoading] = useState(false);
  const [gatewayError, setGatewayError] = useState<string | null>(null);

  // Socket.io callback for real-time messaging
  const handleIncomingMessage = useCallback((msg: GatewayMessage) => {
    setHistoryMessages((prev) => {
      if (prev.some((m) => m.id === msg.id)) return prev;
      return [msg, ...prev];
    });
  }, []);

  const { socketConnected, accounts, setAccounts, qrs, setQrs } = useWhatsAppGateway({
    gatewayUrl,
    apiKey,
    onChatMessage: handleIncomingMessage,
    onError: pushError,
  });

  const [prevConfiguredAccountId, setPrevConfiguredAccountId] = useState(configuredAccountId);
  if (configuredAccountId !== prevConfiguredAccountId) {
    setPrevConfiguredAccountId(configuredAccountId);
    setQrSelectedAccountId(configuredAccountId);
  }

  // Fetch initial gateway details & history
  useEffect(() => {
    if (!gatewayUrl) return;

    let active = true;
    async function loadData() {
      try {
        setLoading(true);
        const accRes = await getGatewayAccounts(gatewayUrl!, apiKey!);

        if (active) {
          setAccounts(accRes.data);
          setGatewayError(null);

          if (accRes.data.length > 0) {
            setQrSelectedAccountId((current) => {
              if (accRes.data.some((a) => a.accountId === current)) return current;
              const configuredAccount = accRes.data.find((a) => a.accountId === configuredAccountId);
              return configuredAccount?.accountId ?? accRes.data[0].accountId;
            });
          }
        }

        try {
          const histRes = await getGatewayHistory(gatewayUrl!, apiKey!, null, 100);
          if (active) {
            setHistoryMessages(histRes.data);
          }
        } catch (histErr: any) {
          console.warn("History failed to load (client might not be ready yet):", histErr);
        }
      } catch (err: any) {
        if (active) {
          setGatewayError(err?.message || "Gateway WhatsApp tidak bisa dimuat");
        }
      } finally {
        if (active) setLoading(false);
      }
    }

    void loadData();

    return () => {
      active = false;
    };
  }, [gatewayUrl, apiKey, setAccounts, configuredAccountId]);

  // Accounts Tab Handlers
  async function handleAddAccount(id: string, label: string) {
    await withFeedback(async () => {
      await createGatewayAccount(gatewayUrl, apiKey, id, label);
      pushSuccess(`Inisialisasi akun '${id}' berhasil dimulai`);

      // Optimistic list update
      setAccounts((prev) => {
        if (prev.some((a) => a.accountId === id)) return prev;
        return [...prev, { accountId: id, ready: false, hasQr: false }];
      });
      setQrSelectedAccountId(id);
      setActiveTab("qr");

      try {
        const res = await getGatewayAccounts(gatewayUrl, apiKey);
        if (res.data.length > 0) setAccounts(res.data);
      } catch {
        // Fallback catch
      }
    }, "add-account");
  }

  async function handleDeleteAccount(id: string) {
    askForConfirmation({
      title: "Hapus akun WhatsApp?",
      body: `Akun '${id}' akan dihapus dari gateway dan session login akan dibersihkan dari disk.`,
      confirmLabel: "Hapus Akun",
      tone: "danger",
      onConfirm: async () => {
        await withFeedback(async () => {
          await deleteGatewayAccount(gatewayUrl, apiKey, id);
          pushSuccess(`Akun '${id}' berhasil dihapus`);
          const res = await getGatewayAccounts(gatewayUrl, apiKey);
          setAccounts(res.data);
        }, "delete-account");
      },
    });
  }

  async function handleRefreshAccounts() {
    await withFeedback(async () => {
      const accRes = await getGatewayAccounts(gatewayUrl, apiKey);
      setAccounts(accRes.data);
      setGatewayError(null);
      
      try {
        const histRes = await getGatewayHistory(gatewayUrl, apiKey, null, 100);
        setHistoryMessages(histRes.data);
      } catch (histErr) {
        console.warn("History failed to load on refresh:", histErr);
      }
      
      pushSuccess("Data gateway berhasil diperbarui");
    }, "refresh-accounts");
  }

  // QR Fetch Fallback
  async function triggerQrFetch(id: string) {
    if (!gatewayUrl) return;
    try {
      const res = await getGatewayAccountQr(gatewayUrl, apiKey, id);
      if (res.data?.qr) {
        setQrs((prev) => ({ ...prev, [id]: res.data.qr }));
      }
    } catch (err: any) {
      pushError(err.message || "QR Code belum siap");
    }
  }

  async function triggerPairingCode(id: string, phone: string): Promise<string | null> {
    if (!gatewayUrl) return null;
    try {
      const { requestGatewayPairingCode } = await import("../../lib/gatewayApi");
      const res = await requestGatewayPairingCode(gatewayUrl, apiKey, id, phone);
      if (res.data?.code) {
        return res.data.code;
      }
      return null;
    } catch (err: any) {
      pushError(err.message || "Gagal mendapatkan pairing code");
      return null;
    }
  }

  

  // Encryption helper
  const canDecrypt = user.role === "admin" || user.role === "petugas";

  const maskText = (text: string, shouldMask: boolean) => {
    if (!text) return "";
    if (!shouldMask) return text;
    return text.replace(/./g, "*");
  };

  const maskPhone = (phone: string, shouldMask: boolean) => {
    if (!phone) return "";
    if (!shouldMask) return phone;
    const clean = phone.replace(/@c\.us$/, "");
    if (clean.length <= 6) return "****";
    return `${clean.substring(0, 4)}*****${clean.substring(clean.length - 2)}`;
  };

  return (
    <section className="grid gap-6">
      {/* Overview Card */}
      <article className="bg-white dark:bg-slate-900 border border-gray-200 dark:border-slate-800 rounded-card p-6 shadow-sm">
        <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4 border-b border-slate-100 dark:border-slate-800 pb-4 mb-6">
          <div>
            <h1 className="text-xl font-bold text-slate-900 dark:text-slate-50 flex items-center gap-2">
              <span>WhatsApp Gateway</span>
              {socketConnected ? (
                <span className="flex items-center gap-1 text-xs font-semibold bg-emerald-50 text-emerald-700 px-2.5 py-1 rounded-full border border-emerald-200">
                  <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
                  Real-time Active
                </span>
              ) : (
                <span className="flex items-center gap-1 text-xs font-semibold bg-slate-100 text-slate-600 px-2.5 py-1 rounded-full border border-slate-200 dark:border-slate-800">
                  <span className="w-2 h-2 rounded-full bg-slate-400" />
                  Polling Only
                </span>
              )}
            </h1>
            <p className="text-sm text-slate-500 dark:text-slate-400 mt-1 flex items-center gap-1.5">
              <span className="inline-flex items-center gap-1 bg-emerald-50 text-emerald-700 text-xs font-semibold px-2 py-0.5 rounded-full border border-emerald-200">
                <span className="w-1.5 h-1.5 rounded-full bg-emerald-500" />
                Gateway
              </span>
              <code className="bg-slate-50 dark:bg-slate-950 px-1 py-0.5 rounded text-xs">{gatewayUrl}</code>
              <span className="text-xs text-slate-400 dark:text-slate-500">Account: {configuredAccountId}</span>
            </p>
          </div>

          <div className="flex gap-2">
            <Button
              type="button"
              variant="outline"
              onClick={handleRefreshAccounts}
            >
              <RefreshCw size={16} className={loading ? "animate-spin" : ""} />
              Refresh Status
            </Button>
          </div>
        </div>

        {gatewayError ? (
          <div className="mb-6 rounded-card border border-rose-200 bg-rose-50 p-4 text-rose-800 flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
            <div>
              <p className="font-bold">Gateway WhatsApp bermasalah</p>
              <p className="text-sm mt-1">{gatewayError}</p>
            </div>
            <Button
              type="button"
              variant="danger"
              onClick={handleRefreshAccounts}
            >
              <RefreshCw size={15} />
              Coba Lagi
            </Button>
          </div>
        ) : null}

        {/* Navigation Tabs */}
        <div className="flex border-b border-slate-200 dark:border-slate-800 mb-6 overflow-x-auto gap-2">
          <Button type="button" variant="outline"
            onClick={() => setActiveTab("accounts")}
            className={`py-3 px-4 font-semibold text-sm border-b-2 transition-all flex items-center gap-2 whitespace-nowrap ${
              activeTab === "accounts"
                ? "border-indigo-600 text-indigo-600"
                : "border-transparent text-slate-600 hover:text-slate-900"
            }`}
          >
            <MessageSquare size={16} />
            Akun Gateway ({accounts.length})
          </Button>
          <Button type="button" variant="outline"
            onClick={() => setActiveTab("qr")}
            className={`py-3 px-4 font-semibold text-sm border-b-2 transition-all flex items-center gap-2 whitespace-nowrap ${
              activeTab === "qr"
                ? "border-indigo-600 text-indigo-600"
                : "border-transparent text-slate-600 hover:text-slate-900"
            }`}
          >
            <Wifi size={16} />
            Scan QR Code
          </Button>
          <Button type="button" variant="outline"
            onClick={() => setActiveTab("history")}
            className={`py-3 px-4 font-semibold text-sm border-b-2 transition-all flex items-center gap-2 whitespace-nowrap ${
              activeTab === "history"
                ? "border-indigo-600 text-indigo-600"
                : "border-transparent text-slate-600 hover:text-slate-900"
            }`}
          >
            <ShieldAlert size={16} />
            Log Percakapan
          </Button>
        </div>

        {/* Tab content 1: Accounts list & Create account */}
        {activeTab === "accounts" && (
          <AccountsTab
            loading={loading}
            accounts={accounts}
            setAccounts={setAccounts}
            gatewayUrl={gatewayUrl}
            apiKey={apiKey}
            gatewayError={gatewayError}
            setGatewayError={setGatewayError}
            canDecrypt={canDecrypt}
            pushSuccess={pushSuccess}
            pushError={pushError}
            onScanQrClick={(id) => {
              setQrSelectedAccountId(id);
              setActiveTab("qr");
            }}
            onDeleteAccount={handleDeleteAccount}
            onAddAccount={handleAddAccount}
          />
        )}

        {/* Tab content 2: Scan QR */}
        {activeTab === "qr" && (
          <QrTab
            accounts={accounts}
            qrs={qrs}
            qrSelectedAccountId={qrSelectedAccountId}
            setQrSelectedAccountId={setQrSelectedAccountId}
            onTriggerQrFetch={triggerQrFetch}
            onTriggerPairingCode={triggerPairingCode}
          />
        )}

        {/* Tab content 3: Chat history / log */}
        {activeTab === "history" && (
          <HistoryTab
            accounts={accounts}
            historyMessages={historyMessages}
            canDecrypt={canDecrypt}
            maskPhone={maskPhone}
            maskText={maskText}
          />
        )}
      </article>
    </section>
  );
}

import { useState } from "react";
import { Button } from "../../../components/ui/Button";
import { Plus, Trash2, RefreshCw } from "lucide-react";
import { inputClassName } from "../../../components/ui";
import { getGatewayAccounts, type GatewayAccount } from "../../../lib/gatewayApi";

type AccountsTabProps = {
  loading: boolean;
  accounts: GatewayAccount[];
  setAccounts: React.Dispatch<React.SetStateAction<GatewayAccount[]>>;
  gatewayUrl: string;
  apiKey?: string;
  gatewayError: string | null;
  setGatewayError: React.Dispatch<React.SetStateAction<string | null>>;
  canDecrypt: boolean;
  pushSuccess: (msg: string) => void;
  pushError: (msg: string) => void;
  onScanQrClick: (id: string) => void;
  onDeleteAccount: (id: string) => void;
  onAddAccount: (id: string, label: string) => Promise<void>;
};

export function AccountsTab({
  loading,
  accounts,
  setAccounts,
  gatewayUrl,
  apiKey,
  gatewayError,
  setGatewayError,
  canDecrypt,
  pushSuccess,
  pushError,
  onScanQrClick,
  onDeleteAccount,
  onAddAccount,
}: AccountsTabProps) {
  const [newAccountId, setNewAccountId] = useState("");
  const [newAccountLabel, setNewAccountLabel] = useState("");

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newAccountId.trim()) {
      pushError("Account ID wajib diisi");
      return;
    }
    await onAddAccount(newAccountId, newAccountLabel);
    setNewAccountId("");
    setNewAccountLabel("");
  };

  return (
    <div className="grid md:grid-cols-3 gap-6">
      {/* Account List */}
      <div className="md:col-span-2 space-y-4">
        <h3 className="text-md font-bold text-slate-900 dark:text-slate-50">Daftar Akun WhatsApp</h3>
        {loading ? (
          <div className="space-y-3">
            {[1, 2].map((i) => (
              <div key={i} className="h-24 rounded-xl bg-slate-100 animate-pulse" />
            ))}
          </div>
        ) : accounts.length === 0 ? (
          <div className="text-center p-8 bg-slate-50 dark:bg-slate-950 rounded-xl border border-slate-200 dark:border-slate-800">
            {gatewayError ? (
              <>
                <p className="font-semibold text-rose-600 mb-1">Gateway tidak dapat dijangkau</p>
                <p className="text-xs text-slate-500 dark:text-slate-400">Pastikan service WhatsApp Gateway berjalan di <code>{gatewayUrl}</code></p>
              </>
            ) : (
              <>
                <p className="font-semibold text-slate-700 dark:text-slate-300 mb-1">Belum ada akun gateway terdaftar</p>
                <p className="text-xs text-slate-500 dark:text-slate-400 mb-4">Tambahkan akun baru di panel sebelah kanan, atau tunggu sebentar jika gateway baru saja dimulai.</p>
                {canDecrypt && apiKey && (
                  <Button
                    type="button"
                    variant="primary"
                    size="sm"
                    onClick={async () => {
                      try {
                        const res = await getGatewayAccounts(gatewayUrl, apiKey!);
                        setAccounts(res.data);
                        setGatewayError(null);
                        pushSuccess("Daftar akun diperbarui");
                      } catch (err: any) {
                        pushError(err?.message || "Gagal memuat akun");
                      }
                    }}
                  >
                    Refresh Daftar Akun
                  </Button>
                )}
              </>
            )}
          </div>
        ) : (
          <div className="grid sm:grid-cols-2 gap-4">
            {accounts.map((acc) => (
              <div
                key={acc.accountId}
                className="border border-slate-200 dark:border-slate-800 rounded-xl p-5 bg-white dark:bg-slate-900 shadow-sm flex flex-col justify-between hover:border-slate-300 transition-colors"
              >
                <div className="flex items-start justify-between mb-4">
                  <div>
                    <h4 className="font-bold text-slate-950 text-md">{acc.accountId}</h4>
                    <p className="text-xs text-slate-400 dark:text-slate-500 mt-0.5">WhatsApp Client Account</p>
                  </div>
                  {acc.ready ? (
                    <span className="flex items-center gap-1.5 text-xs font-semibold bg-emerald-50 text-emerald-700 border border-emerald-200 px-2 py-0.5 rounded-full">
                      <span className="w-1.5 h-1.5 rounded-full bg-emerald-500" />
                      Connected
                    </span>
                  ) : acc.hasQr ? (
                    <span className="flex items-center gap-1.5 text-xs font-semibold bg-amber-50 text-amber-700 border border-amber-200 px-2 py-0.5 rounded-full">
                      <span className="w-1.5 h-1.5 rounded-full bg-amber-500 animate-pulse" />
                      Scan QR Needed
                    </span>
                  ) : (
                    <span className="flex items-center gap-1.5 text-xs font-semibold bg-slate-50 dark:bg-slate-950 text-slate-500 dark:text-slate-400 border border-slate-200 dark:border-slate-800 px-2 py-0.5 rounded-full">
                      <span className="w-1.5 h-1.5 rounded-full bg-slate-400" />
                      Offline
                    </span>
                  )}
                </div>

                <div className="flex gap-2 mt-2 pt-2 border-t border-slate-50 justify-end">
                  {canDecrypt && !acc.ready && (
                    <Button
                      type="button"
                      variant="primary"
                      size="sm"
                      onClick={() => onScanQrClick(acc.accountId)}
                      className="!bg-indigo-50 hover:!bg-indigo-100 !text-indigo-600 hover:!text-indigo-700 border-transparent"
                    >
                      Scan QR
                    </Button>
                  )}
                  {canDecrypt && (
                    <Button
                      type="button"
                      variant="danger"
                      size="sm"
                      onClick={() => onDeleteAccount(acc.accountId)}
                      title="Hapus Akun"
                    >
                      <Trash2 size={15} />
                    </Button>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Create Account Form */}
      {canDecrypt ? (
        <div className="bg-slate-50 dark:bg-slate-950 p-5 rounded-card border border-slate-200 dark:border-slate-800 h-fit">
          <h3 className="text-md font-bold text-slate-900 dark:text-slate-50 mb-4">Tambah Akun Baru</h3>

          {/* API key missing warning */}
          {!apiKey && (
            <div className="mb-4 rounded-xl border border-amber-200 bg-amber-50 p-3 text-xs text-amber-800">
              <p className="font-bold mb-1">ÔÜá API Key belum dikonfigurasi</p>
              <p>Buka <strong>Pengaturan ÔåÆ WhatsApp Gateway</strong> dan isi field <code>wa_api_key</code> agar sama dengan nilai <code>API_KEY</code> di file <code>whatsapp/.env</code>.</p>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-4">
            <label className="block">
              <span className="text-xs font-semibold text-slate-600 block mb-1">Account ID (slug / nama)</span>
              <input
                type="text"
                required
                value={newAccountId}
                onChange={(e) => setNewAccountId(e.target.value.replace(/[^a-zA-Z0-9-_]/g, ""))}
                placeholder="Contoh: CS-Admin-1"
                className={inputClassName()}
              />
              <span className="text-[10px] text-slate-400 dark:text-slate-500 block mt-1">Hanya huruf, angka, dash, dan underscore.</span>
            </label>

            <label className="block">
              <span className="text-xs font-semibold text-slate-600 block mb-1">Label Deskripsi</span>
              <input
                type="text"
                value={newAccountLabel}
                onChange={(e) => setNewAccountLabel(e.target.value)}
                placeholder="Contoh: Akun Customer Service Utama"
                className={inputClassName()}
              />
            </label>

            <Button
              type="submit"
              variant="primary"
              disabled={!apiKey}
              className="w-full flex justify-center gap-2"
            >
              <Plus size={16} />
              Daftarkan & Inisialisasi
            </Button>
          </form>
        </div>
      ) : (
        <div className="bg-slate-50 dark:bg-slate-950 p-5 rounded-card border border-slate-200 dark:border-slate-800 h-fit text-center text-slate-500 dark:text-slate-400 text-xs">
          Anda login sebagai Viewer. Hak akses pengelolaan dinonaktifkan.
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useRef } from "react";
import { Button } from "../../../components/ui/Button";
import { type GatewayAccount, type ChatbotSession, type ContactForm, type AutoReplyRule, type ChatbotSettings } from "../../../lib/gatewayApi";
import { inputClassName } from "../../../components/ui";
import { Bot, Sliders, PlusCircle, CheckCircle2, XCircle, Trash2, Key, ToggleLeft, ToggleRight, Phone, Clock, FileText, User, Pencil, X } from "lucide-react";

type ChatbotTabProps = {
  gatewayUrl: string;
  accounts: GatewayAccount[];
  canDecrypt: boolean;
  chatbotSettings: ChatbotSettings;
  onSaveChatbotSettings: (settings: ChatbotSettings) => Promise<void>;
  autoReplyRules: AutoReplyRule[];
  onAddAutoReplyRule: (rule: {
    accountId: string;
    keyword: string;
    reply: string;
    matchType: AutoReplyRule["match_type"];
    priority: number;
    image?: File;
  }) => Promise<void>;
  onUpdateAutoReplyRule: (id: string, rule: {
    accountId: string;
    keyword: string;
    reply: string;
    matchType: AutoReplyRule["match_type"];
    priority: number;
    image?: File;
  }) => Promise<void>;
  onToggleAutoReplyRule: (rule: AutoReplyRule) => Promise<void>;
  onDeleteAutoReplyRule: (id: string) => Promise<void>;
  chatbotSessions: ChatbotSession[];
  onResetSession: (phone: string) => void;
  contactForms: ContactForm[];
  maskPhone: (phone: string, shouldMask: boolean) => string;
  view?: "rules" | "sessions" | "all";
};

export function ChatbotTab({
  gatewayUrl,
  accounts,
  canDecrypt,
  chatbotSettings,
  onSaveChatbotSettings,
  autoReplyRules,
  onAddAutoReplyRule,
  onUpdateAutoReplyRule,
  onToggleAutoReplyRule,
  onDeleteAutoReplyRule,
  chatbotSessions,
  onResetSession,
  contactForms,
  maskPhone,
  view = "all",
}: ChatbotTabProps) {
  const showRules = view === "all" || view === "rules";
  const showSessions = view === "all" || view === "sessions";

  // Local states for chatbot settings form editing
  const [localSettings, setLocalSettings] = useState<ChatbotSettings>(chatbotSettings);

  const [prevSettings, setPrevSettings] = useState(chatbotSettings);
  if (chatbotSettings !== prevSettings) {
    setPrevSettings(chatbotSettings);
    setLocalSettings(chatbotSettings);
  }

  // Local state for auto reply form
  const [autoReplyForm, setAutoReplyForm] = useState({
    accountId: "*",
    keyword: "",
    reply: "",
    matchType: "contains" as AutoReplyRule["match_type"],
    priority: 100,
  });
  const [selectedImage, setSelectedImage] = useState<File | undefined>(undefined);

  // Edit state
  const [editingRule, setEditingRule] = useState<AutoReplyRule | null>(null);
  const [editForm, setEditForm] = useState({
    accountId: "*",
    keyword: "",
    reply: "",
    matchType: "contains" as AutoReplyRule["match_type"],
    priority: 100,
  });
  const [editImage, setEditImage] = useState<File | undefined>(undefined);

  const startEditing = (rule: AutoReplyRule) => {
    setEditingRule(rule);
    setEditForm({
      accountId: rule.account_id || "*",
      keyword: rule.keyword,
      reply: rule.reply,
      matchType: rule.match_type,
      priority: rule.priority,
    });
    setEditImage(undefined);
  };

  const cancelEditing = () => {
    setEditingRule(null);
    setEditImage(undefined);
  };

  const handleSettingsSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    await onSaveChatbotSettings(localSettings);
  };

  const handleAddRuleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!autoReplyForm.keyword.trim() || !autoReplyForm.reply.trim()) {
      return;
    }
    await onAddAutoReplyRule({ ...autoReplyForm, image: selectedImage });
    setAutoReplyForm((current) => ({ ...current, keyword: "", reply: "" }));
    setSelectedImage(undefined);
    const fileInput = document.getElementById("auto-reply-image-input") as HTMLInputElement;
    if (fileInput) fileInput.value = "";
  };

  const handleEditRuleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingRule || !editForm.keyword.trim() || !editForm.reply.trim()) return;
    await onUpdateAutoReplyRule(editingRule.id, { ...editForm, image: editImage });
    cancelEditing();
  };

  return (
    <div className="space-y-8">
      {showRules && (
        <>
          {/* Gateway Accounts Configuration */}
      <div className="grid lg:grid-cols-2 gap-6">
        <form onSubmit={handleSettingsSubmit} className="bg-white dark:bg-slate-900 p-6 rounded-card border border-slate-200 dark:border-slate-800 dark:border-slate-850/70 shadow-sm space-y-5">
          <div className="flex items-start gap-3 border-b border-slate-100 dark:border-slate-800 dark:border-slate-850 pb-4">
            <div className="p-2 bg-indigo-50 dark:bg-indigo-950/50 text-indigo-600 dark:text-indigo-400 rounded-xl">
              <Sliders size={20} />
            </div>
            <div>
              <h3 className="text-sm font-bold text-slate-850 dark:text-slate-100 uppercase tracking-wider">Pengaturan Akun Bot</h3>
              <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">Pilih akun WA untuk chatbot dan auto-reply. Gunakan <code>*</code> untuk semua.</p>
            </div>
          </div>
          
          <div className="space-y-4">
            <label className="block">
              <span className="text-xs font-bold text-slate-700 dark:text-slate-300 dark:text-slate-400 block mb-1.5">Status Chatbot ISP</span>
              <select
                value={localSettings.chatbot_enabled || "1"}
                onChange={(e) => setLocalSettings((current) => ({ ...current, chatbot_enabled: e.target.value }))}
                className={inputClassName()}
              >
                <option value="1">Aktif (On)</option>
                <option value="0">Nonaktif (Off)</option>
              </select>
            </label>

            <label className="block">
              <span className="text-xs font-bold text-slate-700 dark:text-slate-300 dark:text-slate-400 block mb-1.5">Akun Chatbot ISP</span>
              <select
                value={localSettings.chatbot_account_id || "*"}
                onChange={(e) => setLocalSettings((current) => ({ ...current, chatbot_account_id: e.target.value }))}
                className={inputClassName()}
              >
                <option value="*">Semua akun (*)</option>
                {accounts.map((acc) => (
                  <option key={acc.accountId} value={acc.accountId}>{acc.accountId}</option>
                ))}
              </select>
            </label>
            
            <label className="block">
              <span className="text-xs font-bold text-slate-700 dark:text-slate-300 dark:text-slate-400 block mb-1.5">Akun Auto-Response Custom</span>
              <select
                value={localSettings.auto_reply_account_id || "*"}
                onChange={(e) => setLocalSettings((current) => ({ ...current, auto_reply_account_id: e.target.value }))}
                className={inputClassName()}
              >
                <option value="*">Semua akun (*)</option>
                {accounts.map((acc) => (
                  <option key={acc.accountId} value={acc.accountId}>{acc.accountId}</option>
                ))}
              </select>
            </label>
            
            <label className="block">
              <span className="text-xs font-bold text-slate-700 dark:text-slate-300 dark:text-slate-400 block mb-1.5">Urutan Auto-Response</span>
              <select
                value={localSettings.auto_reply_before_chatbot || "1"}
                onChange={(e) => setLocalSettings((current) => ({ ...current, auto_reply_before_chatbot: e.target.value }))}
                className={inputClassName()}
              >
                <option value="1">Auto-response dicek sebelum chatbot</option>
                <option value="0">Auto-response nonaktif untuk alur chatbot</option>
              </select>
            </label>
          </div>
          
          <div className="pt-2">
            <Button type="submit" variant="primary" className="w-full text-center">
              Simpan Pengaturan Bot
            </Button>
          </div>
        </form>

        <form onSubmit={handleAddRuleSubmit} className="bg-white dark:bg-slate-900 p-6 rounded-card border border-slate-200 dark:border-slate-800 dark:border-slate-850/70 shadow-sm space-y-5">
          <div className="flex items-start gap-3 border-b border-slate-100 dark:border-slate-800 dark:border-slate-850 pb-4">
            <div className="p-2 bg-emerald-50 dark:bg-emerald-950/50 text-emerald-600 dark:text-emerald-400 rounded-xl">
              <PlusCircle size={20} />
            </div>
            <div>
              <h3 className="text-sm font-bold text-slate-850 dark:text-slate-100 uppercase tracking-wider">Tambah Auto-Response</h3>
              <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">Balasan cepat kata kunci seperti: harga, jam layanan, rekening, dll.</p>
            </div>
          </div>
          
          <div className="grid sm:grid-cols-2 gap-4">
            <label className="block">
              <span className="text-xs font-bold text-slate-700 dark:text-slate-300 dark:text-slate-400 block mb-1.5">Akun</span>
              <select
                value={autoReplyForm.accountId}
                onChange={(e) => setAutoReplyForm((current) => ({ ...current, accountId: e.target.value }))}
                className={inputClassName()}
              >
                <option value="*">Semua akun (*)</option>
                {accounts.map((acc) => (
                  <option key={acc.accountId} value={acc.accountId}>{acc.accountId}</option>
                ))}
              </select>
            </label>
            
            <label className="block">
              <span className="text-xs font-bold text-slate-700 dark:text-slate-300 dark:text-slate-400 block mb-1.5">Tipe Cocok</span>
              <select
                value={autoReplyForm.matchType}
                onChange={(e) => setAutoReplyForm((current) => ({ ...current, matchType: e.target.value as AutoReplyRule["match_type"] }))}
                className={inputClassName()}
              >
                <option value="contains">Mengandung Kata</option>
                <option value="exact">Sama Persis</option>
                <option value="startsWith">Diawali Kata</option>
                <option value="endsWith">Diakhiri Kata</option>
                <option value="regex">Regex</option>
              </select>
            </label>
          </div>
          
          <div className="grid sm:grid-cols-3 gap-4">
            <label className="block sm:col-span-2">
              <span className="text-xs font-bold text-slate-700 dark:text-slate-300 dark:text-slate-400 block mb-1.5">Keyword</span>
              <input className={inputClassName()} value={autoReplyForm.keyword} onChange={(e) => setAutoReplyForm((current) => ({ ...current, keyword: e.target.value }))} placeholder="contoh: rekening" required />
            </label>
            
            <label className="block">
              <span className="text-xs font-bold text-slate-700 dark:text-slate-300 dark:text-slate-400 block mb-1.5">Prioritas</span>
              <input type="number" className={inputClassName()} value={autoReplyForm.priority} onChange={(e) => setAutoReplyForm((current) => ({ ...current, priority: Number(e.target.value) || 100 }))} />
            </label>
          </div>
          
           <label className="block">
            <span className="text-xs font-bold text-slate-700 dark:text-slate-300 dark:text-slate-400 block mb-1.5">Balasan</span>
            <textarea className={inputClassName()} rows={3} value={autoReplyForm.reply} onChange={(e) => setAutoReplyForm((current) => ({ ...current, reply: e.target.value }))} placeholder="Tulis pesan balasan otomatis..." required />
          </label>

          <label className="block">
            <span className="text-xs font-bold text-slate-700 dark:text-slate-300 dark:text-slate-400 block mb-1.5">Gambar Lampiran (Opsional)</span>
            <input 
              id="auto-reply-image-input"
              type="file" 
              accept="image/*"
              className={inputClassName()} 
              onChange={(e) => setSelectedImage(e.target.files?.[0])}
            />
          </label>
          
          <div className="pt-2">
            <Button type="submit" variant="primary" className="w-full bg-emerald-600 hover:bg-emerald-700 text-center text-white">
              Tambah Rule Baru
            </Button>
          </div>
        </form>
      </div>

      <div className="space-y-4">
        <h3 className="text-md font-bold text-slate-900 dark:text-slate-50 dark:text-slate-150 flex items-center gap-1.5">
          <span className="w-2 h-2 rounded-full bg-emerald-600" />
          Rule Auto-Response ({autoReplyRules.length})
        </h3>

        {/* Inline Edit Panel */}
        {editingRule && (
          <form
            onSubmit={handleEditRuleSubmit}
            className="bg-amber-50 dark:bg-amber-950/20 border border-amber-300 dark:border-amber-700/50 rounded-card p-5 space-y-4 shadow-md"
          >
            <div className="flex items-center justify-between border-b border-amber-200 dark:border-amber-800/40 pb-3">
              <div className="flex items-center gap-2">
                <div className="p-1.5 bg-amber-100 dark:bg-amber-900/40 text-amber-700 dark:text-amber-400 rounded-lg">
                  <Pencil size={15} />
                </div>
                <span className="text-sm font-bold text-amber-800 dark:text-amber-300">Edit Rule: <span className="font-mono">{editingRule.keyword}</span></span>
              </div>
                <Button type="button" variant="outline" size="sm" onClick={cancelEditing} className="!p-1.5 !gap-0 hover:bg-amber-100 dark:hover:bg-amber-900/30 text-amber-600 dark:text-amber-400 border-transparent">
                  <X size={16} />
                </Button>
            </div>
            <div className="grid sm:grid-cols-2 gap-4">
              <label className="block">
                <span className="text-xs font-bold text-slate-700 dark:text-slate-300 dark:text-slate-400 block mb-1.5">Akun</span>
                <select value={editForm.accountId} onChange={(e) => setEditForm((c) => ({ ...c, accountId: e.target.value }))} className={inputClassName()}>
                  <option value="*">Semua akun (*)</option>
                  {accounts.map((acc) => (<option key={acc.accountId} value={acc.accountId}>{acc.accountId}</option>))}
                </select>
              </label>
              <label className="block">
                <span className="text-xs font-bold text-slate-700 dark:text-slate-300 dark:text-slate-400 block mb-1.5">Tipe Cocok</span>
                <select value={editForm.matchType} onChange={(e) => setEditForm((c) => ({ ...c, matchType: e.target.value as AutoReplyRule["match_type"] }))} className={inputClassName()}>
                  <option value="contains">Mengandung Kata</option>
                  <option value="exact">Sama Persis</option>
                  <option value="startsWith">Diawali Kata</option>
                  <option value="endsWith">Diakhiri Kata</option>
                  <option value="regex">Regex</option>
                </select>
              </label>
            </div>
            <div className="grid sm:grid-cols-3 gap-4">
              <label className="block sm:col-span-2">
                <span className="text-xs font-bold text-slate-700 dark:text-slate-300 dark:text-slate-400 block mb-1.5">Keyword</span>
                <input className={inputClassName()} value={editForm.keyword} onChange={(e) => setEditForm((c) => ({ ...c, keyword: e.target.value }))} required />
              </label>
              <label className="block">
                <span className="text-xs font-bold text-slate-700 dark:text-slate-300 dark:text-slate-400 block mb-1.5">Prioritas</span>
                <input type="number" className={inputClassName()} value={editForm.priority} onChange={(e) => setEditForm((c) => ({ ...c, priority: Number(e.target.value) || 100 }))} />
              </label>
            </div>
            <label className="block">
              <span className="text-xs font-bold text-slate-700 dark:text-slate-300 dark:text-slate-400 block mb-1.5">Balasan</span>
              <textarea className={inputClassName()} rows={3} value={editForm.reply} onChange={(e) => setEditForm((c) => ({ ...c, reply: e.target.value }))} required />
            </label>
            <label className="block">
              <span className="text-xs font-bold text-slate-700 dark:text-slate-300 dark:text-slate-400 block mb-1.5">Gambar Lampiran Baru (Opsional ÔÇö kosongkan untuk mempertahankan gambar lama)</span>
              <input id="edit-reply-image-input" type="file" accept="image/*" className={inputClassName()} onChange={(e) => setEditImage(e.target.files?.[0])} />
            </label>
            {editingRule.image_path && !editImage && (
              <div className="flex items-center gap-2 text-xs text-amber-700 dark:text-amber-400 bg-amber-100/60 dark:bg-amber-900/20 px-3 py-2 rounded-lg border border-amber-200 dark:border-amber-800/40">
                <span>Gambar saat ini akan dipertahankan (pilih file baru untuk menggantinya).</span>
              </div>
            )}
            <div className="flex gap-2 pt-1">
                <Button type="submit" variant="primary" className="flex-1 bg-amber-500 hover:bg-amber-600 text-center">
                  Simpan Perubahan
                </Button>
                <Button type="button" variant="outline" onClick={cancelEditing}>
                  Batal
                </Button>
            </div>
          </form>
        )}

        {autoReplyRules.length === 0 ? (
          <div className="text-center py-6 bg-slate-50 dark:bg-slate-950 dark:bg-slate-900/30 border border-slate-200 dark:border-slate-800 rounded-xl text-slate-500 dark:text-slate-400">
            Belum ada rule auto-response custom.
          </div>
        ) : (
          <div className="grid md:grid-cols-2 gap-4">
            {autoReplyRules.map((rule) => (
              <div key={rule.id} className={`border border-slate-200 dark:border-slate-800 border-l-4 ${rule.enabled ? "border-l-emerald-500" : "border-l-slate-300 dark:border-l-slate-700"} rounded-xl p-5 bg-white dark:bg-slate-900 shadow-sm hover:shadow-md transition-all duration-200`}>
                <div className="flex items-start justify-between gap-3">
                  <div>
                    <span className="text-[10px] uppercase font-bold text-slate-400 dark:text-slate-500 tracking-wider">Kata Kunci</span>
                    <p className="font-bold text-slate-900 dark:text-slate-50 dark:text-slate-100 text-sm font-mono mt-0.5">{rule.keyword}</p>
                  </div>
                  <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full border ${rule.enabled ? "bg-emerald-50 border-emerald-200 text-emerald-700 dark:bg-emerald-950/40 dark:text-emerald-400 dark:border-emerald-900" : "bg-slate-55 bg-slate-100 border-slate-250 text-slate-650 dark:bg-slate-900 dark:border-slate-800 dark:text-slate-500"}`}>
                    {rule.enabled ? "AKTIF" : "NONAKTIF"}
                  </span>
                </div>
                
                <div className="mt-3 bg-slate-50 dark:bg-slate-950 dark:bg-slate-950/50 p-3 rounded-lg border border-slate-100 dark:border-slate-800 dark:border-slate-850">
                  <p className="text-xs text-slate-700 dark:text-slate-300 whitespace-pre-wrap leading-relaxed">{rule.reply}</p>
                </div>
                
                {rule.image_path && (
                  <div className="mt-3 overflow-hidden rounded-lg border border-slate-100 dark:border-slate-800 dark:border-slate-850 bg-slate-50 dark:bg-slate-950 dark:bg-slate-950/50 flex items-center justify-center p-2">
                    <img 
                      src={`${gatewayUrl.replace(/\/$/, '')}/uploads/${rule.image_path}`} 
                      alt={`Lampiran untuk ${rule.keyword}`} 
                      className="max-h-24 max-w-full rounded-md object-contain"
                    />
                  </div>
                )}
                
                <div className="flex items-center justify-between mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 dark:border-slate-850">
                  <div className="text-[10px] text-slate-450 dark:text-slate-500 flex flex-wrap gap-2">
                    <span>Akun: <strong className="text-slate-700 dark:text-slate-300 dark:text-slate-350">{rule.account_id || "*"}</strong></span>
                    <span>ÔÇó</span>
                    <span>Tipe: <strong className="text-slate-700 dark:text-slate-300 dark:text-slate-350">{rule.match_type}</strong></span>
                    <span>ÔÇó</span>
                    <span>Prio: <strong className="text-slate-700 dark:text-slate-300 dark:text-slate-350">{rule.priority}</strong></span>
                  </div>
                  {canDecrypt ? (
                    <div className="flex gap-1">
                        <Button 
                          onClick={() => startEditing(rule)} 
                          type="button" 
                          variant="secondary"
                          size="sm"
                          title="Edit Rule"
                          className="!p-1.5 text-amber-600 bg-amber-50 hover:bg-amber-100 dark:bg-amber-950/45 dark:text-amber-400 dark:hover:bg-amber-900/50"
                        >
                          <Pencil size={15} />
                        </Button>
                        <Button 
                          onClick={() => onToggleAutoReplyRule(rule)} 
                          type="button" 
                          variant="secondary"
                          size="sm"
                          title={rule.enabled ? "Nonaktifkan Rule" : "Aktifkan Rule"}
                          className="!p-1.5 text-indigo-600 bg-indigo-50 hover:bg-indigo-100 dark:bg-indigo-950/45 dark:text-indigo-400 dark:hover:bg-indigo-900/50"
                        >
                          {rule.enabled ? <ToggleRight size={18} /> : <ToggleLeft size={18} />}
                        </Button>
                        <Button 
                          onClick={() => onDeleteAutoReplyRule(rule.id)} 
                          type="button" 
                          variant="danger"
                          size="sm"
                          title="Hapus Rule"
                          className="!p-1.5"
                        >
                          <Trash2 size={16} />
                        </Button>
                    </div>
                  ) : null}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </>
  )}

      {showSessions && (
        <>
          {/* Active Sessions List */}
      <div className="space-y-4">
        <h3 className="text-md font-bold text-slate-900 dark:text-slate-50 dark:text-slate-150 flex items-center gap-1.5">
          <span className="w-2 h-2 rounded-full bg-indigo-600" />
          Sesi Chatbot Aktif ({chatbotSessions.length})
        </h3>
        {chatbotSessions.length === 0 ? (
          <div className="text-center py-6 bg-slate-50 dark:bg-slate-950 dark:bg-slate-900/30 border border-slate-200 dark:border-slate-800 rounded-xl text-slate-500 dark:text-slate-400">
            Tidak ada sesi percakapan chatbot aktif saat ini.
          </div>
        ) : (
          <div className="grid sm:grid-cols-2 md:grid-cols-3 gap-4">
            {chatbotSessions.map((session) => (
              <div
                key={session.phone}
                className="border border-slate-200 dark:border-slate-800 dark:border-slate-850 border-t-2 border-t-indigo-500 rounded-xl p-5 bg-white dark:bg-slate-900 shadow-sm hover:shadow-md transition-all duration-200 flex flex-col justify-between"
              >
                <div>
                  <div className="flex justify-between items-center mb-3">
                    <div className="flex items-center gap-2">
                      <div className="p-1.5 bg-indigo-50 dark:bg-indigo-950/40 text-indigo-650 dark:text-indigo-400 rounded-lg">
                        <Phone size={14} />
                      </div>
                      <h4 className="font-bold text-slate-850 dark:text-slate-100 font-mono text-xs">
                        {maskPhone(session.phone, !canDecrypt)}
                      </h4>
                    </div>
                    <span className="text-[9px] bg-indigo-50 border border-indigo-200 text-indigo-750 px-2 py-0.5 rounded-full font-bold dark:bg-indigo-950/45 dark:text-indigo-400 dark:border-indigo-900 uppercase tracking-wider">
                      {session.state}
                    </span>
                  </div>
                  
                  <div className="flex items-center gap-1.5 text-xs text-slate-500 dark:text-slate-400 mb-3 bg-slate-50 dark:bg-slate-950 dark:bg-slate-950/30 py-1 px-2.5 rounded-lg border border-slate-100 dark:border-slate-800 dark:border-slate-850 w-fit">
                    <span className="w-1.5 h-1.5 rounded-full bg-slate-400" />
                    <span>Akun: <strong className="text-slate-755 dark:text-slate-300 font-mono">{session.account_id}</strong></span>
                  </div>
                  
                  {Object.keys(session.form_data).length > 0 && (
                    <div className="bg-slate-50/50 dark:bg-slate-950/40 p-3 rounded-xl border border-slate-150 dark:border-slate-850/60 mb-3">
                      <p className="text-[9px] uppercase font-bold text-slate-400 dark:text-slate-500 tracking-wider mb-2">Formulir Isian:</p>
                      <div className="grid grid-cols-2 gap-2 text-xs">
                        {Object.entries(session.form_data).map(([key, val]) => (
                          <div key={key} className="flex flex-col min-w-0">
                            <span className="text-[9px] text-slate-400 dark:text-slate-500 font-bold uppercase">{key.replace(/_/g, " ")}</span>
                            <span className="text-slate-800 dark:text-slate-100 dark:text-slate-300 truncate font-semibold font-sans mt-0.5 text-xs" title={String(val)}>{String(val)}</span>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}
                </div>

                <div className="flex justify-between items-center pt-3 border-t border-slate-100 dark:border-slate-800 dark:border-slate-850 mt-2">
                  <span className="text-[10px] text-slate-400 dark:text-slate-500 flex items-center gap-1">
                    <Clock size={12} />
                    {new Date(session.updated_at).toLocaleTimeString("id-ID")}
                  </span>
                  {canDecrypt && (
                      <Button
                        type="button"
                        variant="danger"
                        size="sm"
                        onClick={() => onResetSession(session.phone)}
                        className="!px-2.5 !py-1.5 !text-[10px]"
                      >
                        Reset Sesi
                      </Button>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Submitted Forms List */}
      <div className="space-y-4">
        <h3 className="text-md font-bold text-slate-900 dark:text-slate-50 dark:text-slate-150 flex items-center gap-1.5 border-t border-slate-100 dark:border-slate-800 dark:border-slate-850 pt-6">
          <span className="w-2 h-2 rounded-full bg-emerald-600" />
          Registrasi & Tiket Masuk via WhatsApp ({contactForms.length})
        </h3>
        {contactForms.length === 0 ? (
          <div className="text-center py-8 bg-slate-50 dark:bg-slate-950 dark:bg-slate-900/30 border border-slate-200 dark:border-slate-800 rounded-xl text-slate-500 dark:text-slate-400">
            Belum ada formulir pendaftaran atau keluhan support yang dikirim pelanggan.
          </div>
        ) : (
          <div className="border border-slate-200 dark:border-slate-800 rounded-card overflow-hidden shadow-sm bg-white dark:bg-slate-900">
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse bg-white dark:bg-slate-900 min-w-[700px]">
                <thead className="bg-slate-50 dark:bg-slate-950 text-slate-500 dark:text-slate-400 text-xs font-bold uppercase border-b border-slate-200 dark:border-slate-800">
                  <tr>
                    <th className="px-6 py-4">Tanggal</th>
                    <th className="px-6 py-4">Tipe</th>
                    <th className="px-6 py-4">WhatsApp</th>
                    <th className="px-6 py-4">Detail Data Formulir</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 dark:divide-slate-800 text-sm">
                  {contactForms.map((form) => {
